import type { RawQ } from "../types";
// Nahw i'rāb of Quranic words: cases and signs, nominal and verbal sentences, kāna and inna, objects, ḥāl and tamyīz, conditions, vocative, diptotes and difficult cases. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  // ---------- Stage 1 (foundation) ----------
  { id: "nhi-001", s: "nahw", g: 1, d: 1, t: ["irab-case", "mudaf-ilayhi"], src: "Ibn Hishām, Qaṭr al-Nadā wa-Ball al-Ṣadā, chapter on the genitive (al-majrūrāt)", v: "1:1", w: 2,
    en: ["What is the case and grammatical function of the highlighted word in the verse shown?", ["Genitive (majrūr), as the second term of an annexation (muḍāf ilayhi), marked by kasra", "Nominative (marfūʿ), as subject of a nominal sentence, marked by ḍamma", "Accusative (manṣūb), as direct object, marked by fatḥa", "Genitive (majrūr), as a sound masculine plural, marked by yāʾ"], "The word is the second term of an annexation (iḍāfa) to ism, and the second term is always majrūr. As a singular noun it shows this with kasra. The yāʾ sign belongs only to sound masculine plurals and the dual."],
    de: ["Welchen Kasus und welche grammatische Funktion hat das markierte Wort im gezeigten Vers?", ["Genitiv (majrūr) als zweites Glied einer Genitivverbindung (muḍāf ilayhi), gekennzeichnet durch Kasra", "Nominativ (marfūʿ) als Subjekt eines Nominalsatzes, gekennzeichnet durch Ḍamma", "Akkusativ (manṣūb) als direktes Objekt, gekennzeichnet durch Fatḥa", "Genitiv (majrūr) als gesunder maskuliner Plural, gekennzeichnet durch Yāʾ"], "Das Wort ist das zweite Glied einer Genitivverbindung (Iḍāfa) mit ism und steht daher immer im Genitiv. Als Singular zeigt es das mit Kasra. Das Yāʾ als Zeichen gehört nur zum gesunden maskulinen Plural und zum Dual."],
    ar: ["ما إعراب الكلمة المظللة في الآية المعروضة وعلامته؟", ["مضاف إليه مجرور وعلامة جرّه الكسرة", "مبتدأ مرفوع وعلامة رفعه الضمة", "مفعول به منصوب وعلامة نصبه الفتحة", "اسم مجرور وعلامة جرّه الياء لأنه جمع مذكر سالم"], "الكلمة مضاف إليه لكلمة «اسم»، والمضاف إليه مجرور دائمًا، وعلامة جرّه هنا الكسرة لأنه مفرد. أما الياء فعلامة الجر في جمع المذكر السالم والمثنى فقط."] },

  { id: "nhi-002", s: "nahw", g: 1, d: 1, t: ["mubtada-khabar", "irab-case"], src: "Ibn Hishām, Qaṭr al-Nadā, chapter on the mubtadaʾ and the khabar", v: "1:2", w: 1,
    en: ["In the verse shown, what is the grammatical role of the highlighted word (in the reading of Ḥafṣ)?", ["Mubtadaʾ, nominative, with ḍamma", "Fāʿil, nominative, with ḍamma", "Mafʿūl muṭlaq, accusative, with fatḥa", "Muḍāf ilayhi, genitive, with kasra"], "The nominal sentence begins with this definite noun as mubtadaʾ; the khabar is the following prepositional phrase. In the reading of Ḥafṣ it is marfūʿ with ḍamma. There is no verb before it, so it cannot be a fāʿil."],
    de: ["Welche grammatische Rolle hat das markierte Wort im gezeigten Vers (in der Lesart von Ḥafṣ)?", ["Mubtadaʾ im Nominativ mit Ḍamma", "Fāʿil im Nominativ mit Ḍamma", "Mafʿūl muṭlaq im Akkusativ mit Fatḥa", "Muḍāf ilayhi im Genitiv mit Kasra"], "Der Nominalsatz beginnt mit diesem bestimmten Nomen als Mubtadaʾ; das Ḫabar ist die folgende Präpositionalgruppe. In der Lesart von Ḥafṣ steht es im Nominativ mit Ḍamma. Vor ihm steht kein Verb, also kann es kein Fāʿil sein."],
    ar: ["ما إعراب الكلمة المظللة في الآية المعروضة (برواية حفص)؟", ["مبتدأ مرفوع وعلامة رفعه الضمة", "فاعل مرفوع وعلامة رفعه الضمة", "مفعول مطلق منصوب وعلامة نصبه الفتحة", "مضاف إليه مجرور وعلامة جرّه الكسرة"], "الجملة اسمية بدأت بهذا الاسم المعرّف مبتدأً، وخبره الجار والمجرور بعده. وهو مرفوع بالضمة في رواية حفص. ولا فعل قبله فلا يصح أن يكون فاعلًا."] },

  { id: "nhi-003", s: "nahw", g: 2, d: 2, t: ["mubtada-khabar", "jar-wa-majrur"], src: "Ibn Hishām, Mughnī al-Labīb, on the prepositional phrase as khabar", v: "1:2", w: 2,
    en: ["The highlighted word is the object of a preposition. What does the whole prepositional phrase (preposition plus this word) do in the sentence?", ["It serves as the khabar of the mubtadaʾ, attached to an understood word such as ‘established’", "It serves as the fāʿil of the sentence", "It serves as a ḥāl describing the mubtadaʾ", "It serves as the object (mafʿūl bihi) of an understood verb"], "A prepositional phrase can be the khabar of a mubtadaʾ; grammarians say it is attached to an omitted active participle or verb such as ‘kāʾin’ or ‘istaqarra’. Nothing here is a fāʿil or object, and the mubtadaʾ is definite so a ḥāl is not possible."],
    de: ["Das markierte Wort ist das Objekt einer Präposition. Welche Aufgabe hat die ganze Präpositionalgruppe (Präposition plus dieses Wort) im Satz?", ["Sie ist das Ḫabar des Mubtadaʾ und hängt an einem ergänzten Wort wie ‚bestehend‘", "Sie ist das Fāʿil des Satzes", "Sie ist ein Ḥāl, das das Mubtadaʾ beschreibt", "Sie ist das Objekt (Mafʿūl bihi) eines ergänzten Verbs"], "Eine Präpositionalgruppe kann das Ḫabar eines Mubtadaʾ sein; die Grammatiker sagen, sie hänge an einem ausgelassenen Partizip oder Verb wie ‚kāʾin‘ oder ‚istaqarra‘. Hier gibt es weder Fāʿil noch Objekt, und das Mubtadaʾ ist bestimmt, ein Ḥāl ist also nicht möglich."],
    ar: ["الكلمة المظللة مجرورة بحرف جر. ما وظيفة شبه الجملة (الجار والمجرور) في الجملة؟", ["خبر للمبتدأ متعلق بمحذوف تقديره كائن أو مستقر", "فاعل للجملة", "حال من المبتدأ", "مفعول به لفعل محذوف"], "يقع الجار والمجرور خبرًا للمبتدأ ويتعلق بمحذوف تقديره «كائن» أو «استقرّ». وليس هنا فاعل ولا مفعول، والمبتدأ معرفة فلا يصح مجيء الحال منه."] },

  { id: "nhi-004", s: "nahw", g: 2, d: 2, t: ["sound-masculine-plural", "irab-markers"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the signs of i‘rāb", v: "1:2", w: 4,
    en: ["What is the case of the highlighted word and what is its sign?", ["Genitive (majrūr), as muḍāf ilayhi; the sign is yāʾ because it is a sound masculine plural", "Genitive (majrūr), as muḍāf ilayhi; the sign is kasra because it is a singular noun", "Accusative (manṣūb), as object; the sign is yāʾ because it is a dual", "Nominative (marfūʿ), as khabar; the sign is wāw because it is a sound masculine plural"], "The word is the muḍāf ilayhi of the preceding word and so is majrūr. It is a sound masculine plural, which takes yāʾ in both the genitive and the accusative; in the nominative it would take wāw."],
    de: ["Welchen Kasus hat das markierte Wort und was ist sein Zeichen?", ["Genitiv (majrūr) als Muḍāf ilayhi; das Zeichen ist Yāʾ, weil es ein gesunder maskuliner Plural ist", "Genitiv (majrūr) als Muḍāf ilayhi; das Zeichen ist Kasra, weil es ein Singular ist", "Akkusativ (manṣūb) als Objekt; das Zeichen ist Yāʾ, weil es ein Dual ist", "Nominativ (marfūʿ) als Ḫabar; das Zeichen ist Wāw, weil es ein gesunder maskuliner Plural ist"], "Das Wort ist das Muḍāf ilayhi des vorangehenden Wortes und steht daher im Genitiv. Es ist ein gesunder maskuliner Plural, der im Genitiv und im Akkusativ Yāʾ trägt; im Nominativ hätte er Wāw."],
    ar: ["ما حالة الكلمة المظللة الإعرابية وعلامتها؟", ["مضاف إليه مجرور وعلامة جرّه الياء لأنه جمع مذكر سالم", "مضاف إليه مجرور وعلامة جرّه الكسرة لأنه اسم مفرد", "مفعول به منصوب وعلامة نصبه الياء لأنه مثنى", "خبر مرفوع وعلامة رفعه الواو لأنه جمع مذكر سالم"], "الكلمة مضاف إليه للكلمة قبلها فهي مجرورة، وهي جمع مذكر سالم يُجرّ وينصب بالياء ويرفع بالواو."] },

  { id: "nhi-005", s: "nahw", g: 1, d: 2, t: ["tawabi", "naat"], src: "Ibn Hishām, Qaṭr al-Nadā, chapter on the naʿt (al-tawābiʿ)", v: "1:3", w: 1,
    en: ["What is the highlighted word grammatically, and what case does it therefore take?", ["A naʿt (adjective) that follows the case of the word it describes, so it is genitive", "A khabar that is always nominative", "A mafʿūl bihi that is always accusative", "A ḥāl that is always accusative"], "A naʿt is a follower (tābiʿ): it agrees with the word it describes in case, definiteness, gender and number. Here it describes the divine name and so is majrūr like it."],
    de: ["Was ist das markierte Wort grammatisch, und welchen Kasus hat es deshalb?", ["Ein Naʿt (Adjektiv), das dem Kasus des beschriebenen Wortes folgt, hier also Genitiv", "Ein Ḫabar, das immer im Nominativ steht", "Ein Mafʿūl bihi, das immer im Akkusativ steht", "Ein Ḥāl, das immer im Akkusativ steht"], "Ein Naʿt ist ein Folgewort (Tābiʿ): Es stimmt mit dem beschriebenen Wort in Kasus, Bestimmtheit, Genus und Numerus überein. Hier beschreibt es den göttlichen Namen und steht daher wie dieser im Genitiv."],
    ar: ["ما إعراب الكلمة المظللة، وماذا تتبع في الحالة الإعرابية؟", ["نعت يتبع المنعوت في إعرابه فهو مجرور", "خبر مرفوع دائمًا", "مفعول به منصوب دائمًا", "حال منصوبة دائمًا"], "النعت تابع يوافق المنعوت في إعرابه وتعريفه وتذكيره وعدده. وهنا ينعت لفظ الجلالة فهو مجرور مثله."] },

  { id: "nhi-006", s: "nahw", g: 1, d: 1, t: ["mudaf-ilayhi", "irab-case"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the genitive nouns", v: "1:4", w: 2,
    en: ["Why is the highlighted word in the genitive in the verse shown?", ["Because it is the second term of an annexation (muḍāf ilayhi) to the word before it", "Because a preposition stands directly before it", "Because it is the khabar of a nominal sentence", "Because it follows a verb in the passive voice"], "No preposition occurs here. A noun is genitive when it is the second term of an annexation, and the word before it is its muḍāf. The same word is in turn the muḍāf of the next one."],
    de: ["Warum steht das markierte Wort im gezeigten Vers im Genitiv?", ["Weil es das zweite Glied einer Genitivverbindung (Muḍāf ilayhi) zum vorangehenden Wort ist", "Weil unmittelbar davor eine Präposition steht", "Weil es das Ḫabar eines Nominalsatzes ist", "Weil es auf ein Verb im Passiv folgt"], "Hier steht keine Präposition. Ein Nomen steht im Genitiv, wenn es das zweite Glied einer Iḍāfa ist; das Wort davor ist sein Muḍāf. Dasselbe Wort ist seinerseits das Muḍāf des nächsten Wortes."],
    ar: ["لماذا جاءت الكلمة المظللة مجرورة في الآية المعروضة؟", ["لأنها مضاف إليه للكلمة التي قبلها", "لأن حرف جر يسبقها مباشرة", "لأنها خبر في جملة اسمية", "لأنها تلي فعلًا مبنيًّا للمجهول"], "لا يوجد حرف جر هنا. يُجرّ الاسم إذا كان مضافًا إليه، والكلمة التي قبله مضاف. وهذه الكلمة نفسها مضاف لما بعدها."] },

  { id: "nhi-007", s: "nahw", g: 2, d: 3, t: ["mafulat", "pronouns"], src: "Ibn ʿAqīl, Sharḥ Alfiyyat Ibn Mālik, chapter on the detached pronoun and on fronting the object", v: "1:5", w: 1,
    en: ["The highlighted word is a detached pronoun (ḍamīr munfaṣil). What is its role?", ["Mafʿūl bihi of the following verb, brought forward to express restriction and emphasis, in the position of an accusative", "Fāʿil of the following verb, in the position of a nominative", "Mubtadaʾ of a nominal sentence, in the position of a nominative", "Muḍāf ilayhi, in the position of a genitive"], "Normally the object follows the verb, but here it is put first so that the worship is restricted to God alone. A detached pronoun is used because an attached one cannot come before the verb. It is mabnī, with the position (maḥall) of an accusative."],
    de: ["Das markierte Wort ist ein selbstständiges Pronomen (Ḍamīr munfaṣil). Welche Rolle hat es?", ["Mafʿūl bihi des folgenden Verbs, vorangestellt zur Beschränkung und Betonung, an der Stelle eines Akkusativs", "Fāʿil des folgenden Verbs, an der Stelle eines Nominativs", "Mubtadaʾ eines Nominalsatzes, an der Stelle eines Nominativs", "Muḍāf ilayhi, an der Stelle eines Genitivs"], "Das Objekt steht normalerweise nach dem Verb; hier ist es vorangestellt, damit die Anbetung auf Gott allein beschränkt wird. Ein selbstständiges Pronomen steht, weil ein angehängtes nicht vor dem Verb stehen kann. Es ist mabnī und hat die Stelle (Maḥall) eines Akkusativs."],
    ar: ["الكلمة المظللة ضمير منفصل. ما وظيفتها؟", ["مفعول به مقدّم للفعل بعده لإفادة الحصر والاختصاص، وهو في محل نصب", "فاعل للفعل بعده في محل رفع", "مبتدأ في محل رفع", "مضاف إليه في محل جر"], "الأصل أن يتأخر المفعول، وقد قُدّم هنا ليفيد قصر العبادة على الله وحده. وجاء الضمير منفصلًا لأن المتصل لا يتقدم على الفعل. وهو مبني في محل نصب."] },

  { id: "nhi-008", s: "nahw", g: 2, d: 2, t: ["fiil-mudari", "irab-markers"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the imperfect verb (al-fiʿl al-muḍāriʿ)", v: "1:5", w: 2,
    en: ["What is the state of the highlighted verb and what is its subject (fāʿil)?", ["Imperfect, nominative (marfūʿ) with ḍamma; the fāʿil is an implied pronoun meaning ‘we’", "Imperfect, jussive (majzūm) with sukūn; the fāʿil is an implied pronoun meaning ‘we’", "Imperfect, nominative with ḍamma; the fāʿil is the following pronoun", "Perfect, built on fatḥa; the fāʿil is an implied ‘he’"], "The imperfect is marfūʿ when no particle puts it into the subjunctive or jussive; its sign for this form is ḍamma. Its fāʿil is a hidden pronoun (ḍamīr mustatir) meaning ‘we’, which cannot be shown on the surface here."],
    de: ["In welchem Zustand steht das markierte Verb, und was ist sein Subjekt (Fāʿil)?", ["Imperfekt im Nominativ (marfūʿ) mit Ḍamma; das Fāʿil ist ein verborgenes Pronomen mit der Bedeutung ‚wir‘", "Imperfekt im Jussiv (majzūm) mit Sukūn; das Fāʿil ist ein verborgenes Pronomen mit der Bedeutung ‚wir‘", "Imperfekt im Nominativ mit Ḍamma; das Fāʿil ist das folgende Pronomen", "Perfekt, auf Fatḥa gebaut; das Fāʿil ist ein verborgenes ‚er‘"], "Das Imperfekt ist marfūʿ, wenn keine Partikel es in den Subjunktiv oder Jussiv setzt; sein Zeichen ist hier die Ḍamma. Sein Fāʿil ist ein verborgenes Pronomen (Ḍamīr mustatir) mit der Bedeutung ‚wir‘."],
    ar: ["ما حالة الفعل المظلل الإعرابية، وما فاعله؟", ["فعل مضارع مرفوع وعلامة رفعه الضمة، وفاعله ضمير مستتر تقديره نحن", "فعل مضارع مجزوم وعلامة جزمه السكون، وفاعله ضمير مستتر تقديره نحن", "فعل مضارع مرفوع وعلامة رفعه الضمة، وفاعله الضمير المنفصل بعده", "فعل ماض مبني على الفتح، وفاعله ضمير مستتر تقديره هو"], "المضارع يُرفع إذا لم يسبقه ناصب ولا جازم، وعلامة رفعه هنا الضمة. وفاعله ضمير مستتر وجوبًا تقديره «نحن»."] },

  { id: "nhi-009", s: "nahw", g: 2, d: 3, t: ["mafulat", "two-objects"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on verbs taking two objects (aʿṭā wa-bābuhā)", v: "1:6", w: 2,
    en: ["The verb before the highlighted word takes two objects. What is the highlighted word?", ["The second object (mafʿūl bihi thānin), accusative; the first object is the attached pronoun ‘us’", "The first object, accusative; the second is the attached pronoun", "The fāʿil, nominative", "A ḥāl, accusative"], "The imperative of ‘guide’ takes the pronoun ‘us’ as its first object and the word shown as its second, directly here (the second object can also come with a preposition). It is manṣūb with fatḥa."],
    de: ["Das Verb vor dem markierten Wort hat zwei Objekte. Was ist das markierte Wort?", ["Das zweite Objekt (Mafʿūl bihi ṯānin) im Akkusativ; das erste Objekt ist das angehängte Pronomen ‚uns‘", "Das erste Objekt im Akkusativ; das zweite ist das angehängte Pronomen", "Das Fāʿil im Nominativ", "Ein Ḥāl im Akkusativ"], "Der Imperativ von ‚leiten‘ hat das Pronomen ‚uns‘ als erstes und das gezeigte Wort als zweites Objekt, hier unmittelbar (das zweite Objekt kann auch mit einer Präposition stehen). Es ist manṣūb mit Fatḥa."],
    ar: ["الفعل قبل الكلمة المظللة ينصب مفعولين. ما إعراب الكلمة المظللة؟", ["مفعول به ثانٍ منصوب وعلامة نصبه الفتحة، والأول ضمير «نا»", "مفعول به أول منصوب، والثاني الضمير المتصل", "فاعل مرفوع", "حال منصوبة"], "فعل الأمر هنا ينصب مفعولين: الأول ضمير «نا» والثاني هذه الكلمة (ويجوز تعدّيه إلى الثاني بحرف الجر). وهي منصوبة بالفتحة."] },

  { id: "nhi-010", s: "nahw", g: 1, d: 1, t: ["tawabi", "naat"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the naʿt", v: "1:6", w: 3,
    en: ["The highlighted word is an adjective of the word before it. What case does it take?", ["Accusative (manṣūb), because the word it describes is accusative", "Nominative (marfūʿ), because adjectives are always nominative", "Genitive (majrūr), because it is the last word of the sentence", "Jussive (majzūm), because it follows an imperative"], "A naʿt copies the case of the word it describes. The described word is the second object of the verb and so is accusative. Jussive applies only to verbs."],
    de: ["Das markierte Wort ist ein Adjektiv des vorangehenden Wortes. Welchen Kasus hat es?", ["Akkusativ (manṣūb), weil das beschriebene Wort im Akkusativ steht", "Nominativ (marfūʿ), weil Adjektive immer im Nominativ stehen", "Genitiv (majrūr), weil es das letzte Wort des Satzes ist", "Jussiv (majzūm), weil es auf einen Imperativ folgt"], "Ein Naʿt übernimmt den Kasus des beschriebenen Wortes. Dieses ist das zweite Objekt des Verbs und steht daher im Akkusativ. Der Jussiv gilt nur für Verben."],
    ar: ["الكلمة المظللة نعت للكلمة قبلها. ما حالتها الإعرابية؟", ["منصوبة لأنها تتبع المنعوت المنصوب", "مرفوعة لأن النعت يكون مرفوعًا دائمًا", "مجرورة لأنها آخر كلمة في الجملة", "مجزومة لأنها تلي فعل أمر"], "النعت يتبع منعوته في الإعراب، والمنعوت مفعول به ثانٍ منصوب، فالنعت منصوب. أما الجزم فللأفعال المضارعة فقط."] },

  { id: "nhi-011", s: "nahw", g: 2, d: 2, t: ["attached-pronouns", "mafulat"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on pronouns", v: "1:6", w: 1,
    en: ["The highlighted word is an imperative with the attached pronoun ‘nā’ (us). What is the position of ‘nā’?", ["Accusative (maḥall naṣb), the first object of the verb", "Nominative (maḥall rafʿ), the subject of the verb", "Genitive (maḥall jarr), annexed to the verb", "No position, it is only a plural marker"], "The subject of an imperative is an implied ‘you’. The attached ‘nā’ is the thing the guidance is asked for, so it is the object, in the position of an accusative; the pronoun is mabnī so no sign appears."],
    de: ["Das markierte Wort ist ein Imperativ mit dem angehängten Pronomen ‚nā‘ (uns). Welche Stellung hat ‚nā‘?", ["Akkusativ (Maḥall naṣb), erstes Objekt des Verbs", "Nominativ (Maḥall rafʿ), Subjekt des Verbs", "Genitiv (Maḥall jarr), an das Verb angeschlossen", "Keine Stellung, es ist nur ein Pluralzeichen"], "Das Subjekt eines Imperativs ist ein verborgenes ‚anta‘ (2. Person). Das angehängte ‚nā‘ ist das, wofür um Leitung gebeten wird, also das Objekt an der Stelle eines Akkusativs; das Pronomen ist mabnī, sodass kein Zeichen erscheint."],
    ar: ["الكلمة المظللة فعل أمر اتصل به الضمير «نا». ما موقع «نا» الإعرابي؟", ["ضمير متصل مبني في محل نصب مفعول به أول", "ضمير متصل مبني في محل رفع فاعل", "ضمير متصل مبني في محل جر مضاف إليه", "لا محل له من الإعراب فهو علامة جمع"], "فاعل فعل الأمر ضمير مستتر تقديره «أنت». أما «نا» فهو المطلوب له الهداية فهو مفعول به في محل نصب، والضمير مبني لا تظهر عليه علامة."] },

  { id: "nhi-012", s: "nahw", g: 2, d: 2, t: ["atf", "sound-masculine-plural"], src: "Ibn Hishām, Qaṭr al-Nadā, chapter on the conjunction (al-ʿaṭf)", v: "1:7", w: 9,
    en: ["What is the highlighted word grammatically?", ["Genitive, joined by ʿaṭf to the preceding genitive word; its sign is yāʾ", "Accusative, a ḥāl; its sign is fatḥa", "Nominative, a khabar; its sign is wāw", "Genitive, a muḍāf; its sign is kasra"], "The conjunction wa- joins this word to the genitive word before it, so it is genitive too. It is a sound masculine plural, hence the yāʾ sign. The negative particle before it does not change this."],
    de: ["Was ist das markierte Wort grammatisch?", ["Genitiv, durch ʿAṭf mit dem vorangehenden Genitivwort verbunden; sein Zeichen ist Yāʾ", "Akkusativ, ein Ḥāl; sein Zeichen ist Fatḥa", "Nominativ, ein Ḫabar; sein Zeichen ist Wāw", "Genitiv, ein Muḍāf; sein Zeichen ist Kasra"], "Die Konjunktion wa- verbindet dieses Wort mit dem vorangehenden Genitivwort, daher steht es ebenfalls im Genitiv. Es ist ein gesunder maskuliner Plural, deshalb das Zeichen Yāʾ. Die Negationspartikel davor ändert daran nichts."],
    ar: ["ما إعراب الكلمة المظللة؟", ["معطوف على كلمة مجرورة قبلها فهو مجرور وعلامة جرّه الياء", "حال منصوبة وعلامة نصبها الفتحة", "خبر مرفوع وعلامة رفعه الواو", "مضاف مجرور وعلامة جرّه الكسرة"], "حرف العطف يربط هذه الكلمة بالمجرور قبلها فتتبعه في الجر، وهي جمع مذكر سالم علامة جرّه الياء. ولا يغيّر حرف النفي قبلها ذلك."] },

  { id: "nhi-013", s: "nahw", g: 2, d: 2, t: ["demonstrative-pronouns", "mubtada-khabar"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on demonstratives (ismā al-ishāra)", v: "2:2", w: 1,
    en: ["The verse starts with a demonstrative pronoun. What is its position?", ["Mabnī (indeclinable) in the position of a nominative, as mubtadaʾ", "Mabnī in the position of an accusative, as object", "Muʿrab nominative with ḍamma, as fāʿil", "Mabnī in the position of a genitive, as muḍāf ilayhi"], "Demonstratives are mabnī, so they show no case sign; they only have a position (maḥall). At the head of the nominal sentence the demonstrative is the mubtadaʾ, so its position is rafʿ."],
    de: ["Der Vers beginnt mit einem Demonstrativpronomen. Welche Stellung hat es?", ["Mabnī (unveränderlich) an der Stelle eines Nominativs, als Mubtadaʾ", "Mabnī an der Stelle eines Akkusativs, als Objekt", "Muʿrab im Nominativ mit Ḍamma, als Fāʿil", "Mabnī an der Stelle eines Genitivs, als Muḍāf ilayhi"], "Demonstrativa sind mabnī und zeigen daher kein Kasuszeichen, sondern haben nur eine Stellung (Maḥall). Am Anfang des Nominalsatzes ist das Demonstrativum das Mubtadaʾ, also steht es an der Stelle eines Nominativs."],
    ar: ["تبدأ الآية باسم إشارة. ما موقعه الإعرابي؟", ["اسم إشارة مبني في محل رفع مبتدأ", "اسم إشارة مبني في محل نصب مفعول به", "اسم معرب مرفوع بالضمة فاعل", "اسم إشارة مبني في محل جر مضاف إليه"], "أسماء الإشارة مبنية فلا تظهر عليها علامة إعراب بل لها محل. وفي أول الجملة الاسمية هو المبتدأ فمحله الرفع."] },

  { id: "nhi-014", s: "nahw", g: 2, d: 2, t: ["muqaddar-markers", "irab-markers"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the signs of i‘rāb; Ibn Hishām, Qaṭr al-Nadā, on the maqṣūr", v: "2:2", w: 6,
    en: ["The highlighted word ends in alif maqṣūra. How is its case sign shown?", ["As an implied sign (muqaddar) on the final alif, since the alif cannot carry a vowel", "As a visible ḍamma, fatḥa or kasra on the last letter", "As a yāʾ in the genitive and accusative", "It has no case at all because it is an indeclinable word"], "Nouns ending in alif maqṣūra (the maqṣūr) are declinable, but their final alif cannot take a vowel, so the nominative, accusative and genitive signs are only implied. The tanwīn shown in writing does not change this."],
    de: ["Das markierte Wort endet auf Alif maqṣūra. Wie zeigt sich sein Kasuszeichen?", ["Als gedachtes Zeichen (muqaddar) auf dem letzten Alif, da Alif keinen Vokal tragen kann", "Als sichtbare Ḍamma, Fatḥa oder Kasra auf dem letzten Buchstaben", "Als Yāʾ im Genitiv und Akkusativ", "Es hat gar keinen Kasus, weil es unveränderlich ist"], "Nomen auf Alif maqṣūra (das Maqṣūr) sind deklinierbar, aber ihr letztes Alif kann keinen Vokal tragen, daher werden die Zeichen für Nominativ, Akkusativ und Genitiv nur gedacht. Das geschriebene Tanwīn ändert daran nichts."],
    ar: ["الكلمة المظللة تنتهي بألف مقصورة. كيف تظهر علامة إعرابها؟", ["علامة مقدّرة على الألف منع من ظهورها التعذّر", "ضمة أو فتحة أو كسرة ظاهرة على آخرها", "ياء في الجر والنصب", "لا إعراب لها لأنها مبنية"], "الاسم المقصور معرب لكن آخره ألف لا تقبل الحركة، فتقدَّر عليه علامات الرفع والنصب والجر للتعذّر. والتنوين المكتوب لا يغيّر ذلك."] },

  { id: "nhi-015", s: "nahw", g: 2, d: 2, t: ["afal-khamsa", "irab-markers"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the five verbs (al-afʿāl al-khamsa)", v: "2:3", w: 2,
    en: ["What is the sign of the nominative state of the highlighted verb?", ["The presence of the final nūn, since it is one of the five verbs", "A ḍamma on the last letter", "The omission of the final nūn", "A sukūn on the last letter"], "Verbs of the pattern yafʿalūna/yafʿalāni/tafʿalīna are the ‘five verbs’; they are raised by keeping the nūn and put into the jussive or subjunctive by dropping it. The wāw is the subject pronoun."],
    de: ["Was ist das Zeichen für den Nominativ (Rafʿ) des markierten Verbs?", ["Das Vorhandensein des letzten Nūn, da es zu den ‚fünf Verben‘ gehört", "Eine Ḍamma auf dem letzten Buchstaben", "Der Wegfall des letzten Nūn", "Ein Sukūn auf dem letzten Buchstaben"], "Verben nach dem Muster yafʿalūna/yafʿalāni/tafʿalīna sind die ‚fünf Verben‘; sie stehen im Rafʿ mit Nūn und im Jussiv oder Subjunktiv ohne Nūn. Das Wāw ist das Subjektpronomen."],
    ar: ["ما علامة رفع الفعل المظلل؟", ["ثبوت النون لأنه من الأفعال الخمسة", "الضمة على آخره", "حذف النون", "السكون على آخره"], "الأفعال الخمسة (يفعلان، تفعلان، يفعلون، تفعلون، تفعلين) ترفع بثبوت النون وتنصب وتجزم بحذفها. والواو فيه ضمير متصل في محل رفع فاعل."] },

  { id: "nhi-016", s: "nahw", g: 1, d: 1, t: ["mafulat", "maful-bihi"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the accusative nouns", v: "2:3", w: 5,
    en: ["What is the highlighted word in the clause ‘and they establish …’?", ["The direct object (mafʿūl bihi), accusative with fatḥa", "The subject (fāʿil), nominative with ḍamma", "The khabar, nominative with ḍamma", "The muḍāf ilayhi, genitive with kasra"], "The verb already has its subject (the wāw). The word that receives the action is the direct object, which is always manṣūb; the sign is fatḥa."],
    de: ["Was ist das markierte Wort in der Wendung ‚und sie verrichten …‘?", ["Das direkte Objekt (Mafʿūl bihi) im Akkusativ mit Fatḥa", "Das Subjekt (Fāʿil) im Nominativ mit Ḍamma", "Das Ḫabar im Nominativ mit Ḍamma", "Das Muḍāf ilayhi im Genitiv mit Kasra"], "Das Verb hat sein Subjekt schon (das Wāw). Das Wort, das die Handlung empfängt, ist das direkte Objekt; es steht immer im Akkusativ, das Zeichen ist Fatḥa."],
    ar: ["ما إعراب الكلمة المظللة في جملة «ويقيمون ...»؟", ["مفعول به منصوب وعلامة نصبه الفتحة", "فاعل مرفوع وعلامة رفعه الضمة", "خبر مرفوع وعلامة رفعه الضمة", "مضاف إليه مجرور وعلامة جرّه الكسرة"], "للفعل فاعله وهو واو الجماعة. والكلمة التي وقع عليها الفعل مفعول به، وهو منصوب دائمًا وعلامة نصبه الفتحة."] },

  { id: "nhi-017", s: "nahw", g: 1, d: 2, t: ["inna-sisters", "irab-case"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on inna and its sisters", v: "2:6", w: 2,
    en: ["The verse opens with the particle inna. What is the highlighted word, which follows it?", ["Its ism, in the position of an accusative", "Its khabar, in the position of a nominative", "The subject of a verb, nominative", "A muḍāf ilayhi, genitive"], "Inna and its sisters enter a nominal sentence, put the mubtadaʾ into the accusative (as their ism) and keep the khabar in the nominative. The word shown is a relative pronoun, which is mabnī, so it only has the position of an accusative."],
    de: ["Der Vers beginnt mit der Partikel inna. Was ist das darauffolgende markierte Wort?", ["Ihr Ism an der Stelle eines Akkusativs", "Ihr Ḫabar an der Stelle eines Nominativs", "Das Subjekt eines Verbs im Nominativ", "Ein Muḍāf ilayhi im Genitiv"], "Inna und ihre Schwestern treten vor einen Nominalsatz, setzen das Mubtadaʾ in den Akkusativ (als ihr Ism) und lassen das Ḫabar im Nominativ. Das gezeigte Wort ist ein Relativpronomen und damit mabnī, hat also nur die Stellung eines Akkusativs."],
    ar: ["تبدأ الآية بالحرف «إنّ». ما إعراب الكلمة المظللة التي تليه؟", ["اسم «إنّ» مبني في محل نصب", "خبر «إنّ» في محل رفع", "فاعل مرفوع", "مضاف إليه مجرور"], "«إنّ» وأخواتها تدخل على الجملة الاسمية فتنصب المبتدأ ويسمى اسمها وترفع الخبر. والكلمة هنا اسم موصول مبني فمحلها النصب."] },

  { id: "nhi-018", s: "nahw", g: 2, d: 3, t: ["amr", "afal-khamsa"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the building of the imperative", v: "2:43", w: 1,
    en: ["The highlighted word is an imperative addressed to a group. On what is it built (mabnī)?", ["On the omission of the nūn, since its imperfect is one of the five verbs", "On fatḥa", "On sukūn", "On the omission of the weak letter"], "The imperative is built on whatever marks the jussive of its imperfect. For the five verbs this is the dropping of the nūn, so the plural imperative ends in -ū without nūn."],
    de: ["Das markierte Wort ist ein Imperativ an eine Gruppe. Worauf ist er gebaut (mabnī)?", ["Auf dem Wegfall des Nūn, da sein Imperfekt zu den fünf Verben gehört", "Auf Fatḥa", "Auf Sukūn", "Auf dem Wegfall des schwachen Buchstabens"], "Der Imperativ ist auf dem gebaut, was den Jussiv seines Imperfekts kennzeichnet. Bei den fünf Verben ist das der Wegfall des Nūn, daher endet der Plural-Imperativ auf -ū ohne Nūn."],
    ar: ["الكلمة المظللة فعل أمر موجّه لجماعة. على م يُبنى؟", ["على حذف النون لأن مضارعه من الأفعال الخمسة", "على الفتح", "على السكون", "على حذف حرف العلة"], "يُبنى فعل الأمر على ما يُجزم به مضارعه، والأفعال الخمسة تُجزم بحذف النون، فيُبنى أمرها على حذف النون."] },

  { id: "nhi-019", s: "nahw", g: 1, d: 2, t: ["passive-voice", "naib-fail"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the substitute for the agent (nāʾib al-fāʿil)", v: "2:183", w: 6,
    en: ["The verb before the highlighted word is passive. What is the highlighted word?", ["Nāʾib al-fāʿil (the deputy of the subject), nominative with ḍamma", "Mafʿūl bihi, accusative with fatḥa", "Khabar of a nominal sentence, nominative", "Muḍāf ilayhi, genitive"], "When a verb is passive, the agent is dropped and the object takes its place in the nominative: it is called nāʾib al-fāʿil (or the fāʿil of the passive). It therefore has ḍamma."],
    de: ["Das Verb vor dem markierten Wort steht im Passiv. Was ist das markierte Wort?", ["Nāʾib al-fāʿil (Stellvertreter des Subjekts) im Nominativ mit Ḍamma", "Mafʿūl bihi im Akkusativ mit Fatḥa", "Ḫabar eines Nominalsatzes im Nominativ", "Muḍāf ilayhi im Genitiv"], "Steht ein Verb im Passiv, fällt der Handelnde weg und das Objekt rückt im Nominativ an seine Stelle: Es heißt Nāʾib al-fāʿil. Deshalb hat es Ḍamma."],
    ar: ["الفعل قبل الكلمة المظللة مبني للمجهول. ما إعراب الكلمة المظللة؟", ["نائب فاعل مرفوع وعلامة رفعه الضمة", "مفعول به منصوب وعلامة نصبه الفتحة", "خبر مرفوع", "مضاف إليه مجرور"], "إذا بُني الفعل للمجهول حُذف الفاعل وناب عنه المفعول به فيُرفع ويسمى نائب فاعل."] },

  { id: "nhi-020", s: "nahw", g: 2, d: 2, t: ["sound-masculine-plural", "mudaf-ilayhi"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the genitive nouns", v: "2:43", w: 7,
    en: ["The highlighted word follows the adverb ‘with’ (maʿa). What is its case and sign?", ["Genitive, as muḍāf ilayhi of maʿa; the sign is yāʾ", "Accusative, as an adverb; the sign is fatḥa", "Nominative, as khabar; the sign is wāw", "Genitive, as object of a preposition; the sign is kasra"], "Maʿa is a noun of place (ẓarf) and is itself annexed to the following word, which is therefore the muḍāf ilayhi and majrūr. As a sound masculine plural it shows this with yāʾ."],
    de: ["Das markierte Wort folgt auf das Adverb ‚mit‘ (maʿa). Welchen Kasus und welches Zeichen hat es?", ["Genitiv als Muḍāf ilayhi von maʿa; das Zeichen ist Yāʾ", "Akkusativ als Adverb; das Zeichen ist Fatḥa", "Nominativ als Ḫabar; das Zeichen ist Wāw", "Genitiv als Objekt einer Präposition; das Zeichen ist Kasra"], "Maʿa ist ein Ortsnomen (Ẓarf) und wird selbst mit dem folgenden Wort verbunden, das daher Muḍāf ilayhi und majrūr ist. Als gesunder maskuliner Plural zeigt es das mit Yāʾ."],
    ar: ["الكلمة المظللة تلي الظرف «مع». ما إعرابها وعلامته؟", ["مضاف إليه مجرور وعلامة جرّه الياء", "ظرف منصوب وعلامة نصبه الفتحة", "خبر مرفوع وعلامة رفعه الواو", "اسم مجرور بحرف جر وعلامة جرّه الكسرة"], "«مع» ظرف مضاف، وما بعده مضاف إليه مجرور، وهو جمع مذكر سالم علامة جرّه الياء."] },

  { id: "nhi-021", s: "nahw", g: 2, d: 2, t: ["fail", "irab-case"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the fāʿil", v: "2:255", w: 10,
    en: ["Who does the action of the verb ‘it takes hold of him’ in the verse shown? What is the highlighted word?", ["The fāʿil, nominative with ḍamma (tanwīn)", "The mafʿūl bihi, accusative", "The mubtadaʾ of a new sentence", "The ḥāl, accusative"], "The attached pronoun is the object; the agent of the verb is the word that follows it. A fāʿil is always marfūʿ, here with ḍammatān (tanwīn) because it is indefinite."],
    de: ["Wer führt die Handlung des Verbs ‚es ergreift ihn‘ im gezeigten Vers aus? Was ist das markierte Wort?", ["Das Fāʿil im Nominativ mit Ḍamma (Tanwīn)", "Das Mafʿūl bihi im Akkusativ", "Das Mubtadaʾ eines neuen Satzes", "Der Ḥāl im Akkusativ"], "Das angehängte Pronomen ist das Objekt; der Handelnde ist das folgende Wort. Ein Fāʿil steht immer im Nominativ, hier mit Ḍammatān (Tanwīn), weil es unbestimmt ist."],
    ar: ["من فاعل الفعل «تأخذه» في الآية المعروضة؟ وما إعراب الكلمة المظللة؟", ["فاعل مرفوع وعلامة رفعه الضمة (الضمتان للتنوين)", "مفعول به منصوب", "مبتدأ لجملة جديدة", "حال منصوبة"], "الضمير المتصل بالفعل هو المفعول به، أما الفاعل فهو الكلمة المظللة، والفاعل مرفوع دائمًا، وهو نكرة فيُنوَّن."] },

  { id: "nhi-022", s: "nahw", g: 1, d: 1, t: ["mubtada-khabar", "irab-case"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the mubtadaʾ and khabar", v: "3:185", w: 1,
    en: ["The verse opens with ‘kull’ followed by ‘nafs’. What is the highlighted word ‘kull’?", ["Mubtadaʾ, nominative with ḍamma, and ‘nafs’ is its muḍāf ilayhi", "Fāʿil, nominative, and ‘nafs’ is its object", "Khabar, nominative, and ‘nafs’ is its subject", "Mafʿūl muṭlaq, accusative, and ‘nafs’ is its adjective"], "The sentence is nominal: ‘kull’ starts it as mubtadaʾ and is annexed to ‘nafs’. The khabar is the next noun, which is itself annexed to ‘death’."],
    de: ["Der Vers beginnt mit ‚kull‘ vor ‚nafs‘. Was ist das markierte Wort ‚kull‘?", ["Mubtadaʾ im Nominativ mit Ḍamma, und ‚nafs‘ ist sein Muḍāf ilayhi", "Fāʿil im Nominativ, und ‚nafs‘ ist sein Objekt", "Ḫabar im Nominativ, und ‚nafs‘ ist sein Subjekt", "Mafʿūl muṭlaq im Akkusativ, und ‚nafs‘ ist sein Adjektiv"], "Der Satz ist ein Nominalsatz: ‚kull‘ eröffnet ihn als Mubtadaʾ und ist mit ‚nafs‘ verbunden. Das Ḫabar ist das nächste Nomen, das seinerseits mit ‚Tod‘ verbunden ist."],
    ar: ["تبدأ الآية بكلمة «كل» تليها «نفس». ما إعراب «كل» المظللة؟", ["مبتدأ مرفوع وعلامة رفعه الضمة، و«نفس» مضاف إليه", "فاعل مرفوع و«نفس» مفعوله", "خبر مرفوع و«نفس» مبتدأ", "مفعول مطلق منصوب و«نفس» نعته"], "الجملة اسمية بدأت بـ«كل» مبتدأً مضافًا إلى «نفس»، وخبرها الاسم التالي وهو مضاف إلى «الموت»."] },

  { id: "nhi-023", s: "nahw", g: 1, d: 1, t: ["tawabi", "naat"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the naʿt", v: "4:1", w: 16,
    en: ["The highlighted word describes the word before it (‘men’). What is its case?", ["Accusative (manṣūb), as naʿt of an accusative word", "Nominative (marfūʿ), as khabar", "Genitive (majrūr), as muḍāf ilayhi", "Jussive (majzūm), as a verb"], "The preceding noun is the object of ‘He spread’ and is accusative. Its adjective follows it in case, so it is accusative as well, with tanwīn because it is indefinite."],
    de: ["Das markierte Wort beschreibt das vorangehende Wort (‚Männer‘). Welchen Kasus hat es?", ["Akkusativ (manṣūb) als Naʿt eines Akkusativwortes", "Nominativ (marfūʿ) als Ḫabar", "Genitiv (majrūr) als Muḍāf ilayhi", "Jussiv (majzūm) als Verb"], "Das vorangehende Nomen ist das Objekt von ‚er verbreitete‘ und steht im Akkusativ. Sein Adjektiv folgt ihm im Kasus, steht also ebenfalls im Akkusativ, mit Tanwīn, weil es unbestimmt ist."],
    ar: ["الكلمة المظللة تصف الكلمة قبلها («رجالًا»). ما حالتها الإعرابية؟", ["نعت منصوب تبعًا للمنعوت المنصوب", "خبر مرفوع", "مضاف إليه مجرور", "فعل مجزوم"], "الاسم قبلها مفعول به للفعل «بثّ» فهو منصوب، ونعته يتبعه في النصب، وهو منوّن لأنه نكرة."] },

  { id: "nhi-024", s: "nahw", g: 2, d: 3, t: ["hal-tamyiz", "mafulat"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the ḥāl", v: "4:28", w: 8,
    en: ["The highlighted word describes the state of ‘the human being’ at the time of creation. What is it?", ["A ḥāl (circumstantial accusative), manṣūb with tanwīn fatḥa", "A khabar of a mubtadaʾ, marfūʿ", "A tamyīz of a number", "A muḍāf ilayhi, majrūr"], "A ḥāl is an indefinite accusative that tells in what state the doer or object is while the action happens. The verb is passive, ‘was created’, and the word shown gives the state of its deputy subject."],
    de: ["Das markierte Wort beschreibt den Zustand des ‚Menschen‘ bei der Erschaffung. Was ist es?", ["Ein Ḥāl (Zustandsakkusativ), manṣūb mit Tanwīn-Fatḥa", "Ein Ḫabar eines Mubtadaʾ, marfūʿ", "Ein Tamyīz einer Zahl", "Ein Muḍāf ilayhi, majrūr"], "Ein Ḥāl ist ein unbestimmter Akkusativ, der angibt, in welchem Zustand sich der Handelnde oder das Objekt bei der Handlung befindet. Das Verb ist passiv, ‚wurde erschaffen‘, und das Wort gibt den Zustand seines Stellvertreter-Subjekts an."],
    ar: ["الكلمة المظللة تصف حال «الإنسان» وقت خلقه. ما إعرابها؟", ["حال منصوبة وعلامة نصبها الفتحة (تنوين الفتح)", "خبر مرفوع لمبتدأ", "تمييز لعدد", "مضاف إليه مجرور"], "الحال اسم نكرة منصوب يبيّن هيئة صاحبه وقت وقوع الفعل. والفعل هنا مبني للمجهول ونائب فاعله «الإنسان» صاحب الحال."] },

  { id: "nhi-025", s: "nahw", g: 1, d: 1, t: ["fail", "atf"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapters on the fāʿil and the ʿaṭf", v: "110:1", w: 3,
    en: ["After the verb ‘came’, what is the highlighted word?", ["The fāʿil, nominative with ḍamma, annexed to the next word", "The mafʿūl bihi, accusative", "A ḥāl, accusative", "The khabar of inna"], "The verb ‘came’ needs a doer. The highlighted word is that doer, marfūʿ with ḍamma, and it is annexed to the following name; the conjoined word after it shares the nominative case."],
    de: ["Was ist das markierte Wort nach dem Verb ‚kam‘?", ["Das Fāʿil im Nominativ mit Ḍamma, mit dem nächsten Wort verbunden", "Das Mafʿūl bihi im Akkusativ", "Ein Ḥāl im Akkusativ", "Das Ḫabar von inna"], "Das Verb ‚kam‘ braucht einen Handelnden. Das markierte Wort ist dieser Handelnde, marfūʿ mit Ḍamma, und es ist mit dem folgenden Namen verbunden; das angeschlossene Wort danach teilt den Nominativ."],
    ar: ["ما إعراب الكلمة المظللة بعد الفعل «جاء»؟", ["فاعل مرفوع وعلامة رفعه الضمة وهو مضاف", "مفعول به منصوب", "حال منصوبة", "خبر «إنّ»"], "الفعل «جاء» يحتاج إلى فاعل، والكلمة المظللة هي الفاعل مرفوعة بالضمة ومضافة إلى ما بعدها، والمعطوف عليها مرفوع مثلها."] },

  { id: "nhi-026", s: "nahw", g: 1, d: 2, t: ["jazm-nasb", "irab-markers"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the jussive (al-jazm)", v: "112:3", w: 2,
    en: ["The highlighted verb follows the particle ‘lam’. What is its state and sign?", ["Jussive (majzūm), with sukūn on the last letter", "Nominative (marfūʿ), with ḍamma", "Subjunctive (manṣūb), with fatḥa", "Built (mabnī) on fatḥa as a perfect verb"], "The particle ‘lam’ puts an imperfect verb into the jussive and gives it the past meaning. The sign for a sound verb is sukūn, which here is shown (and lightly vocalised with kasra when reading on)."],
    de: ["Das markierte Verb folgt auf die Partikel ‚lam‘. Welchen Zustand und welches Zeichen hat es?", ["Jussiv (majzūm) mit Sukūn auf dem letzten Buchstaben", "Nominativ (marfūʿ) mit Ḍamma", "Subjunktiv (manṣūb) mit Fatḥa", "Gebaut (mabnī) auf Fatḥa als Perfekt"], "Die Partikel ‚lam‘ setzt ein Imperfekt in den Jussiv und verleiht ihm vergangene Bedeutung. Das Zeichen bei einem gesunden Verb ist Sukūn, das hier geschrieben steht (beim Weiterlesen wird es mit Kasra gelöst)."],
    ar: ["الفعل المظلل مسبوق بـ«لم». ما حالته وعلامتها؟", ["مضارع مجزوم وعلامة جزمه السكون", "مضارع مرفوع وعلامة رفعه الضمة", "مضارع منصوب وعلامة نصبه الفتحة", "فعل ماض مبني على الفتح"], "«لم» حرف جزم ينفي المضارع ويقلب زمنه إلى الماضي، وعلامة جزم الفعل الصحيح السكون."] },

  { id: "nhi-027", s: "nahw", g: 1, d: 1, t: ["inna-sisters", "irab-case"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on inna and its sisters", v: "103:2", w: 2,
    en: ["In the verse shown, what is the highlighted word?", ["The ism of inna, accusative with fatḥa", "The khabar of inna, nominative", "The fāʿil of a verb, nominative", "A muḍāf ilayhi, genitive"], "Inna puts the noun that follows it into the accusative as its ism, and its khabar comes later (here a prepositional phrase)."],
    de: ["Was ist das markierte Wort im gezeigten Vers?", ["Das Ism von inna im Akkusativ mit Fatḥa", "Das Ḫabar von inna im Nominativ", "Das Fāʿil eines Verbs im Nominativ", "Ein Muḍāf ilayhi im Genitiv"], "Inna setzt das folgende Nomen als ihr Ism in den Akkusativ; ihr Ḫabar folgt später (hier eine Präpositionalgruppe)."],
    ar: ["ما إعراب الكلمة المظللة في الآية المعروضة؟", ["اسم «إنّ» منصوب وعلامة نصبه الفتحة", "خبر «إنّ» مرفوع", "فاعل لفعل مرفوع", "مضاف إليه مجرور"], "تنصب «إنّ» الاسم بعدها ويسمى اسمها، ويأتي خبرها لاحقًا وهو هنا شبه جملة."] },

  { id: "nhi-028", s: "nahw", g: 2, d: 3, t: ["sound-feminine-plural", "irab-markers"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the signs of i‘rāb", v: "103:3", w: 5,
    en: ["The highlighted word is the object of ‘they did’. What is its sign of case?", ["Kasra, standing in for fatḥa, because it is a sound feminine plural", "Fatḥa, as for every accusative", "Yāʾ, because it is a plural", "Sukūn, because it is a verb"], "The sound feminine plural (jamʿ muʾannath sālim) takes kasra in place of fatḥa in the accusative. It is manṣūb as object of ‘they did’."],
    de: ["Das markierte Wort ist das Objekt von ‚sie taten‘. Welches Kasuszeichen hat es?", ["Kasra anstelle von Fatḥa, weil es ein gesunder femininer Plural ist", "Fatḥa wie jeder Akkusativ", "Yāʾ, weil es ein Plural ist", "Sukūn, weil es ein Verb ist"], "Der gesunde feminine Plural (Jamʿ muʾannaṯ sālim) hat im Akkusativ Kasra anstelle von Fatḥa. Er ist manṣūb als Objekt von ‚sie taten‘."],
    ar: ["الكلمة المظللة مفعول به للفعل «عملوا». ما علامة نصبها؟", ["الكسرة نيابة عن الفتحة لأنها جمع مؤنث سالم", "الفتحة كسائر المنصوبات", "الياء لأنها جمع", "السكون لأنها فعل"], "جمع المؤنث السالم ينصب بالكسرة نيابة عن الفتحة، وهي هنا مفعول به منصوب."] },

  { id: "nhi-029", s: "nahw", g: 2, d: 2, t: ["kana-sisters", "irab-case"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on kāna and its sisters", v: "3:110", w: 2,
    en: ["The verse opens with kāna plus a pronoun. What is the highlighted word that follows?", ["The khabar of kāna, accusative", "The ism of kāna, nominative", "The mafʿūl muṭlaq, accusative", "A muḍāf ilayhi, genitive"], "Kāna puts the subject in the nominative (here the attached pronoun) and the predicate in the accusative: it is the khabar of kāna, which is annexed to the next noun."],
    de: ["Der Vers beginnt mit kāna und einem Pronomen. Was ist das darauffolgende markierte Wort?", ["Das Ḫabar von kāna im Akkusativ", "Das Ism von kāna im Nominativ", "Das Mafʿūl muṭlaq im Akkusativ", "Ein Muḍāf ilayhi im Genitiv"], "Kāna setzt das Subjekt in den Nominativ (hier das angehängte Pronomen) und das Prädikat in den Akkusativ: Es ist das Ḫabar von kāna und mit dem nächsten Nomen verbunden."],
    ar: ["يبدأ الكلام بـ«كان» متصلة بضمير. ما إعراب الكلمة المظللة التالية؟", ["خبر «كان» منصوب", "اسم «كان» مرفوع", "مفعول مطلق منصوب", "مضاف إليه مجرور"], "ترفع «كان» المبتدأ ويسمى اسمها (وهو هنا الضمير المتصل) وتنصب الخبر، والكلمة المظللة خبرها وهي مضافة إلى ما بعدها."] },

  { id: "nhi-030", s: "nahw", g: 2, d: 3, t: ["mabni-muarab", "past-verb"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the perfect verb", v: "2:34", w: 2,
    en: ["The highlighted perfect verb ends with the attached ‘nā’ of the subject. On what is it built?", ["On sukūn, because a movable pronoun of the subject is attached", "On fatḥa, as every perfect verb", "On ḍamma, because a plural wāw is attached", "On the omission of the nūn"], "A perfect verb is normally built on fatḥa, but when a movable subject pronoun (tāʾ, nā, nūn of the feminine) attaches, it is built on sukūn. With a plural wāw it is built on ḍamma instead."],
    de: ["Das markierte Perfekt endet mit dem angehängten ‚nā‘ des Subjekts. Worauf ist es gebaut?", ["Auf Sukūn, weil ein bewegliches Subjektpronomen angehängt ist", "Auf Fatḥa wie jedes Perfekt", "Auf Ḍamma, weil ein Plural-Wāw angehängt ist", "Auf dem Wegfall des Nūn"], "Ein Perfekt ist normalerweise auf Fatḥa gebaut; hängt sich aber ein bewegliches Subjektpronomen (Tāʾ, Nā, Nūn des Femininums) an, ist es auf Sukūn gebaut. Mit einem Plural-Wāw wäre es auf Ḍamma gebaut."],
    ar: ["الفعل الماضي المظلل اتصل به «نا» الفاعلين. على م يُبنى؟", ["على السكون لاتصاله بضمير رفع متحرك", "على الفتح كسائر الأفعال الماضية", "على الضم لاتصاله بواو الجماعة", "على حذف النون"], "الأصل في الماضي البناء على الفتح، فإذا اتصل به ضمير رفع متحرك (التاء، نا، نون النسوة) بُني على السكون، وإذا اتصلت به واو الجماعة بُني على الضم."] },

  { id: "nhi-031", s: "nahw", g: 1, d: 2, t: ["atf", "mafulat"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the ʿaṭf", v: "12:4", w: 11,
    en: ["The highlighted word follows the conjunction wa- after ‘eleven stars’. What is its case and why?", ["Accusative, because it is joined by ʿaṭf to the accusative object ‘stars’", "Nominative, because it starts a new sentence", "Genitive, because it follows the number", "Jussive, because it follows wa-"], "The verb ‘I saw’ governs the whole series. The conjunction wa- links this noun to the preceding accusative object, so it takes the same case."],
    de: ["Das markierte Wort folgt der Konjunktion wa- nach ‚elf Sternen‘. Welchen Kasus hat es und warum?", ["Akkusativ, weil es durch ʿAṭf mit dem Akkusativobjekt ‚Sterne‘ verbunden ist", "Nominativ, weil es einen neuen Satz beginnt", "Genitiv, weil es auf die Zahl folgt", "Jussiv, weil es auf wa- folgt"], "Das Verb ‚ich sah‘ regiert die ganze Reihe. Die Konjunktion wa- verbindet dieses Nomen mit dem vorangehenden Akkusativobjekt, daher hat es denselben Kasus."],
    ar: ["الكلمة المظللة تلي حرف العطف بعد «أحد عشر كوكبًا». ما حالتها الإعرابية ولماذا؟", ["منصوبة لأنها معطوفة على المفعول به المنصوب «كوكبًا»", "مرفوعة لأنها بداية جملة جديدة", "مجرورة لأنها تلي العدد", "مجزومة لأنها تلي الواو"], "الفعل «رأيت» يعمل في المتعاطفات كلها، والواو تعطف هذا الاسم على المفعول به المنصوب فيأخذ إعرابه."] },

  { id: "nhi-032", s: "nahw", g: 2, d: 2, t: ["kana-sisters", "irab-case"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on kāna and its sisters", v: "2:23", w: 20,
    en: ["The highlighted word follows ‘you were’ (kuntum). What is it, and what is its sign?", ["Khabar of kāna, accusative; the sign is yāʾ because it is a sound masculine plural", "Ism of kāna, nominative; the sign is wāw", "Khabar of kāna, accusative; the sign is fatḥa", "Muḍāf ilayhi, genitive; the sign is yāʾ"], "In ‘kuntum ṣādiqīna’ the attached tum is the ism of kāna. The predicate is accusative, and being a sound masculine plural it shows the accusative with yāʾ."],
    de: ["Das markierte Wort folgt auf ‚ihr wart‘ (kuntum). Was ist es, und was ist sein Zeichen?", ["Ḫabar von kāna im Akkusativ; das Zeichen ist Yāʾ, weil es ein gesunder maskuliner Plural ist", "Ism von kāna im Nominativ; das Zeichen ist Wāw", "Ḫabar von kāna im Akkusativ; das Zeichen ist Fatḥa", "Muḍāf ilayhi im Genitiv; das Zeichen ist Yāʾ"], "In ‚kuntum ṣādiqīna‘ ist das angehängte tum das Ism von kāna. Das Prädikat steht im Akkusativ, und als gesunder maskuliner Plural zeigt es den Akkusativ mit Yāʾ."],
    ar: ["الكلمة المظللة تلي «كنتم». ما إعرابها وعلامته؟", ["خبر «كان» منصوب وعلامة نصبه الياء لأنه جمع مذكر سالم", "اسم «كان» مرفوع وعلامة رفعه الواو", "خبر «كان» منصوب وعلامة نصبه الفتحة", "مضاف إليه مجرور وعلامة جرّه الياء"], "في «كنتم صادقين» الضمير «تم» اسم كان، والخبر منصوب، وجمع المذكر السالم ينصب بالياء."] },

  { id: "nhi-033", s: "nahw", g: 2, d: 3, t: ["atf", "fail"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the ʿaṭf", v: "3:18", w: 8,
    en: ["The verse says ‘God bears witness … and the angels …’. What is the highlighted word?", ["Joined by ʿaṭf to the nominative fāʿil, so it is nominative", "A ḥāl, accusative", "The object, accusative", "A muḍāf ilayhi, genitive"], "The verb ‘bears witness’ has God as its subject. The conjunction wa- links the angels to that subject, so the word takes the nominative with ḍamma. The angels are also witnesses, the subject here being multiple."],
    de: ["Der Vers sagt ‚Gott bezeugt … und die Engel …‘. Was ist das markierte Wort?", ["Durch ʿAṭf mit dem Nominativ-Fāʿil verbunden, also Nominativ", "Ein Ḥāl im Akkusativ", "Das Objekt im Akkusativ", "Ein Muḍāf ilayhi im Genitiv"], "Das Verb ‚bezeugt‘ hat Gott als Subjekt. Die Konjunktion wa- verbindet die Engel mit diesem Subjekt, daher steht das Wort im Nominativ mit Ḍamma."],
    ar: ["تقول الآية «شهد الله ... والملائكة». ما إعراب الكلمة المظللة؟", ["معطوف على الفاعل المرفوع فهو مرفوع بالضمة", "حال منصوبة", "مفعول به منصوب", "مضاف إليه مجرور"], "الفعل «شهد» فاعله لفظ الجلالة، وحرف العطف يعطف الملائكة عليه فتُرفع بالضمة."] },

  { id: "nhi-034", s: "nahw", g: 2, d: 2, t: ["munada", "irab-case"], src: "Ibn Hishām, Qaṭr al-Nadā, chapter on the vocative (al-munādā)", v: "7:23", w: 2,
    en: ["The highlighted word is the vocative ‘our Lord’ (the particle of calling is omitted). What is it?", ["Munādā, an annexed noun, accusative with fatḥa", "Mubtadaʾ, nominative", "Fāʿil, nominative", "Majrūr as muḍāf ilayhi"], "A vocative that is annexed to another word (muḍāf) is always accusative. The particle of calling is dropped here, as often in supplications."],
    de: ["Das markierte Wort ist der Vokativ ‚unser Herr‘ (die Anrufpartikel ist weggelassen). Was ist es?", ["Munādā, ein verbundenes Nomen, Akkusativ mit Fatḥa", "Mubtadaʾ im Nominativ", "Fāʿil im Nominativ", "Majrūr als Muḍāf ilayhi"], "Ein Vokativ, der mit einem anderen Wort verbunden ist (Muḍāf), steht immer im Akkusativ. Die Anrufpartikel ist hier weggelassen, wie oft in Bittgebeten."],
    ar: ["الكلمة المظللة منادى بمعنى «ربّنا» (وقد حُذف حرف النداء). ما إعرابها؟", ["منادى مضاف منصوب وعلامة نصبه الفتحة", "مبتدأ مرفوع", "فاعل مرفوع", "اسم مجرور مضاف إليه"], "المنادى المضاف منصوب دائمًا، وقد حُذف حرف النداء كما يكثر في الدعاء."] },

  { id: "nhi-035", s: "nahw", g: 2, d: 3, t: ["afal-khamsa", "irab-markers"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the five verbs", v: "55:13", w: 4,
    en: ["The highlighted verb is a dual form. What is its state and sign?", ["Nominative (marfūʿ), with the nūn kept; the alif is the subject pronoun", "Nominative, with ḍamma on the last letter", "Subjunctive, with the nūn dropped", "Built on sukūn"], "The dual imperfect (yafʿalāni/tafʿalāni) is one of the five verbs; the alif is the subject, and the nūn is kept as sign of the nominative because nothing puts it into the subjunctive or jussive."],
    de: ["Das markierte Verb steht in der Dualform. Welchen Zustand und welches Zeichen hat es?", ["Nominativ (marfūʿ) mit erhaltenem Nūn; das Alif ist das Subjektpronomen", "Nominativ mit Ḍamma auf dem letzten Buchstaben", "Subjunktiv mit Wegfall des Nūn", "Auf Sukūn gebaut"], "Das Dual-Imperfekt (yafʿalāni/tafʿalāni) gehört zu den fünf Verben; das Alif ist das Subjekt, und das Nūn bleibt als Zeichen des Nominativs erhalten, da nichts es in Subjunktiv oder Jussiv setzt."],
    ar: ["الفعل المظلل بصيغة المثنى. ما حالته وعلامتها؟", ["مضارع مرفوع وعلامة رفعه ثبوت النون، والألف ضمير فاعل", "مضارع مرفوع وعلامة رفعه الضمة", "مضارع منصوب بحذف النون", "فعل مبني على السكون"], "المضارع المسند إلى ألف الاثنين من الأفعال الخمسة، يُرفع بثبوت النون، والألف ضمير في محل رفع فاعل."] },

  { id: "nhi-036", s: "nahw", g: 2, d: 3, t: ["mafulat", "two-objects"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on verbs taking two objects", v: "108:1", w: 3,
    en: ["The verb ‘We have given you’ takes two objects. What is the highlighted word?", ["The second object, accusative with fatḥa; the first is the attached ‘you’", "The fāʿil, nominative", "The khabar of inna", "The first object, nominative"], "The attached pronoun ‘ka’ is the recipient and the first object; the thing given is the second object, manṣūb. The ‘we’ is the subject (nā), attached to the verb."],
    de: ["Das Verb ‚Wir haben Ihnen gegeben‘ (zweite Person) hat zwei Objekte. Was ist das markierte Wort?", ["Das zweite Objekt im Akkusativ mit Fatḥa; das erste ist das angehängte Pronomen der zweiten Person", "Das Fāʿil im Nominativ", "Das Ḫabar von inna", "Das erste Objekt im Nominativ"], "Das angehängte Pronomen ‚ka‘ ist der Empfänger und das erste Objekt; das Gegebene ist das zweite Objekt, manṣūb. Das ‚wir‘ ist das Subjekt (nā), das am Verb hängt."],
    ar: ["الفعل «أعطيناك» ينصب مفعولين. ما إعراب الكلمة المظللة؟", ["مفعول به ثانٍ منصوب وعلامة نصبه الفتحة، والأول كاف الخطاب", "فاعل مرفوع", "خبر «إنّ»", "مفعول به أول مرفوع"], "كاف الخطاب هي الآخذ وهي المفعول الأول، والمُعطى هو المفعول الثاني المنصوب، و«نا» ضمير الفاعلين."] },

  { id: "nhi-037", s: "nahw", g: 1, d: 2, t: ["mubtada-khabar", "irab-case"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the mubtadaʾ and khabar", v: "112:2", w: 2,
    en: ["In the short nominal sentence of the verse shown, what is the highlighted word?", ["The khabar, nominative with ḍamma", "The mubtadaʾ, nominative", "The fāʿil, nominative", "The mafʿūl bihi, accusative"], "The first word is the mubtadaʾ (the divine name). The highlighted word completes the meaning as its khabar. Both are marfūʿ, and no verb is present."],
    de: ["Was ist das markierte Wort im kurzen Nominalsatz des gezeigten Verses?", ["Das Ḫabar im Nominativ mit Ḍamma", "Das Mubtadaʾ im Nominativ", "Das Fāʿil im Nominativ", "Das Mafʿūl bihi im Akkusativ"], "Das erste Wort ist das Mubtadaʾ (der göttliche Name). Das markierte Wort vervollständigt die Aussage als Ḫabar. Beide stehen im Nominativ, und es gibt kein Verb."],
    ar: ["ما إعراب الكلمة المظللة في الجملة الاسمية القصيرة بالآية المعروضة؟", ["خبر مرفوع وعلامة رفعه الضمة", "مبتدأ مرفوع", "فاعل مرفوع", "مفعول به منصوب"], "الكلمة الأولى مبتدأ (لفظ الجلالة) والمظللة تتم المعنى فهي خبره، وكلاهما مرفوع ولا فعل في الجملة."] },

  { id: "nhi-038", s: "nahw", g: 1, d: 1, t: ["mafulat", "maful-bihi"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the accusative nouns", v: "2:30", w: 17,
    en: ["What is the highlighted word in the clause ‘and sheds …’?", ["The direct object, accusative with fatḥa", "The subject, nominative", "The khabar, nominative", "A muḍāf ilayhi, genitive"], "The verb ‘sheds’ has a hidden subject; the thing that is shed is its direct object, manṣūb. The sign is fatḥa."],
    de: ["Was ist das markierte Wort im Satzteil ‚und vergießt …‘?", ["Das direkte Objekt im Akkusativ mit Fatḥa", "Das Subjekt im Nominativ", "Das Ḫabar im Nominativ", "Ein Muḍāf ilayhi im Genitiv"], "Das Verb ‚vergießt‘ hat ein verborgenes Subjekt; das, was vergossen wird, ist sein direktes Objekt, manṣūb. Das Zeichen ist Fatḥa."],
    ar: ["ما إعراب الكلمة المظللة في جملة «ويسفك ...»؟", ["مفعول به منصوب وعلامة نصبه الفتحة", "فاعل مرفوع", "خبر مرفوع", "مضاف إليه مجرور"], "للفعل «يسفك» فاعل مستتر، والمسفوك مفعول به منصوب بالفتحة."] },

  { id: "nhi-039", s: "nahw", g: 1, d: 2, t: ["jar-wa-majrur", "irab-case"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the prepositions (ḥurūf al-jarr)", v: "114:1", w: 3,
    en: ["The highlighted word begins with the preposition bi-. What is the status of the whole phrase?", ["A prepositional phrase (jār wa-majrūr) attached to the verb ‘I seek refuge’", "A fāʿil of the verb", "A khabar of a mubtadaʾ", "A muḍāf ilayhi"], "The preposition makes the following noun majrūr, and the phrase is attached to the verb ‘I seek refuge’: it tells in whom the refuge is sought. It is not an independent part of the sentence in the way a fāʿil is."],
    de: ["Das markierte Wort beginnt mit der Präposition bi-. Welchen Status hat die ganze Gruppe?", ["Eine Präpositionalgruppe (Jār wa-majrūr), die am Verb ‚ich suche Zuflucht‘ hängt", "Ein Fāʿil des Verbs", "Ein Ḫabar eines Mubtadaʾ", "Ein Muḍāf ilayhi"], "Die Präposition setzt das folgende Nomen in den Genitiv, und die Gruppe hängt am Verb ‚ich suche Zuflucht‘: Sie sagt, bei wem Zuflucht gesucht wird. Sie ist kein selbstständiger Satzteil wie ein Fāʿil."],
    ar: ["الكلمة المظللة مسبوقة بالباء. ما حكم الجار والمجرور؟", ["جار ومجرور متعلقان بالفعل «أعوذ»", "فاعل للفعل", "خبر لمبتدأ", "مضاف إليه"], "حرف الجر يجرّ الاسم بعده، والجار والمجرور متعلقان بالفعل «أعوذ» يبيّنان من يُستعاذ به، وليسا فاعلًا."] },

  { id: "nhi-040", s: "nahw", g: 1, d: 1, t: ["amr", "mabni-muarab"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the imperative", v: "96:1", w: 1,
    en: ["The highlighted word is a singular imperative of a sound verb. On what is it built, and who is its hidden subject?", ["On sukūn; the hidden subject means ‘you’", "On fatḥa; the hidden subject means ‘he’", "On ḍamma; the hidden subject means ‘we’", "On the omission of the nūn; the hidden subject means ‘they’"], "The imperative of a sound verb for one person is built on sukūn (its jussive form). Its fāʿil is always a hidden ‘anta’ (you)."],
    de: ["Das markierte Wort ist ein Singular-Imperativ eines gesunden Verbs. Worauf ist er gebaut, und wer ist sein verborgenes Subjekt?", ["Auf Sukūn; das verborgene Subjekt bedeutet ‚anta‘ (2. Person)", "Auf Fatḥa; das verborgene Subjekt bedeutet ‚er‘", "Auf Ḍamma; das verborgene Subjekt bedeutet ‚wir‘", "Auf dem Wegfall des Nūn; das verborgene Subjekt bedeutet ‚sie‘"], "Der Imperativ eines gesunden Verbs für eine Person ist auf Sukūn gebaut (seine Jussivform). Sein Fāʿil ist immer ein verborgenes ‚anta‘ (2. Person)."],
    ar: ["الكلمة المظللة فعل أمر لمفرد من الفعل الصحيح. على م يُبنى وما فاعله؟", ["يُبنى على السكون وفاعله ضمير مستتر تقديره أنت", "يُبنى على الفتح وفاعله ضمير مستتر تقديره هو", "يُبنى على الضم وفاعله ضمير مستتر تقديره نحن", "يُبنى على حذف النون وفاعله ضمير مستتر تقديره هم"], "فعل الأمر للمفرد من الفعل الصحيح مبني على السكون، وفاعله ضمير مستتر وجوبًا تقديره «أنت»."] },

  { id: "nhi-041", s: "nahw", g: 1, d: 1, t: ["mudaf-ilayhi", "irab-case"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the genitive nouns", v: "1:4", w: 3,
    en: ["What is the highlighted word, the last word of the verse shown?", ["A muḍāf ilayhi, genitive with kasra", "A mubtadaʾ, nominative with ḍamma", "A fāʿil, nominative with ḍamma", "A mafʿūl bihi, accusative with fatḥa"], "It completes an annexation: the preceding noun is the muḍāf and this one the muḍāf ilayhi, which is always majrūr. Its sign is kasra."],
    de: ["Was ist das markierte Wort, das letzte Wort des gezeigten Verses?", ["Ein Muḍāf ilayhi im Genitiv mit Kasra", "Ein Mubtadaʾ im Nominativ mit Ḍamma", "Ein Fāʿil im Nominativ mit Ḍamma", "Ein Mafʿūl bihi im Akkusativ mit Fatḥa"], "Es vollendet eine Genitivverbindung: Das vorangehende Nomen ist das Muḍāf und dieses das Muḍāf ilayhi, das immer im Genitiv steht. Sein Zeichen ist Kasra."],
    ar: ["ما إعراب الكلمة المظللة، وهي آخر كلمة في الآية المعروضة؟", ["مضاف إليه مجرور وعلامة جرّه الكسرة", "مبتدأ مرفوع وعلامة رفعه الضمة", "فاعل مرفوع وعلامة رفعه الضمة", "مفعول به منصوب وعلامة نصبه الفتحة"], "تكمل الكلمة إضافة: الاسم قبلها مضاف وهي مضاف إليه، والمضاف إليه مجرور دائمًا وعلامته الكسرة."] },

  { id: "nhi-042", s: "nahw", g: 1, d: 1, t: ["mudaf-ilayhi", "irab-case"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the genitive nouns", v: "114:1", w: 4,
    en: ["What is the highlighted word after ‘Lord’ in the verse shown?", ["Muḍāf ilayhi, genitive with kasra", "Fāʿil, nominative", "Khabar, nominative", "Mafʿūl bihi, accusative"], "‘Lord of’ is a muḍāf; the word that completes it is the muḍāf ilayhi and is majrūr, whatever else follows."],
    de: ["Was ist das markierte Wort nach ‚Herr‘ im gezeigten Vers?", ["Muḍāf ilayhi im Genitiv mit Kasra", "Fāʿil im Nominativ", "Ḫabar im Nominativ", "Mafʿūl bihi im Akkusativ"], "‚Herr von‘ ist ein Muḍāf; das Wort, das es vervollständigt, ist das Muḍāf ilayhi und steht im Genitiv."],
    ar: ["ما إعراب الكلمة المظللة بعد «رب» في الآية المعروضة؟", ["مضاف إليه مجرور وعلامة جرّه الكسرة", "فاعل مرفوع", "خبر مرفوع", "مفعول به منصوب"], "«رب» مضاف، والكلمة التي تكمله مضاف إليه مجرور."] },

  { id: "nhi-043", s: "nahw", g: 1, d: 2, t: ["tawabi", "irab-case"], src: "Ibn Hishām, Qaṭr al-Nadā, chapter on the tawābiʿ", v: "2:255", w: 7,
    en: ["The highlighted word is a divine attribute that follows ‘the Ever-Living’. What is its case?", ["Nominative (marfūʿ) with ḍamma, as it agrees with the word before it", "Accusative (manṣūb) with fatḥa", "Genitive (majrūr) with kasra", "Jussive (majzūm)"], "Both attributes are in the nominative, either as naʿt or as further khabars of the mubtadaʾ. In every analysis the word is marfūʿ with ḍamma, never accusative or genitive."],
    de: ["Das markierte Wort ist ein göttliches Attribut nach ‚der Lebendige‘. Welchen Kasus hat es?", ["Nominativ (marfūʿ) mit Ḍamma, da es mit dem Wort davor übereinstimmt", "Akkusativ (manṣūb) mit Fatḥa", "Genitiv (majrūr) mit Kasra", "Jussiv (majzūm)"], "Beide Attribute stehen im Nominativ, entweder als Naʿt oder als weitere Ḫabar des Mubtadaʾ. In jeder Analyse ist das Wort marfūʿ mit Ḍamma, nie Akkusativ oder Genitiv."],
    ar: ["الكلمة المظللة صفة إلهية تأتي بعد «الحي». ما حالتها الإعرابية؟", ["مرفوعة وعلامة رفعها الضمة لأنها توافق ما قبلها", "منصوبة وعلامة نصبها الفتحة", "مجرورة وعلامة جرّها الكسرة", "مجزومة"], "الصفتان كلتاهما مرفوعتان، إما نعتًا وإما خبرين آخرين للمبتدأ، وعلى كل الوجوه الكلمة مرفوعة بالضمة."] },

  { id: "nhi-044", s: "nahw", g: 2, d: 2, t: ["atf", "sound-feminine-plural"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the ʿaṭf", v: "2:255", w: 44,
    en: ["The highlighted word follows ‘and’ after the heavens. What is it?", ["Joined by ʿaṭf to the accusative ‘heavens’, so accusative with fatḥa", "Subject of ‘encompasses’, nominative", "Joined to a genitive, so genitive", "Khabar of a new sentence, nominative"], "The verb ‘encompasses’ has a subject and takes ‘the heavens’ as object. The conjunction wa- adds a second object. ‘Heavens’ is a sound feminine plural with kasra for accusative; this word, a singular, shows fatḥa."],
    de: ["Das markierte Wort folgt nach ‚und‘ auf die Himmel. Was ist es?", ["Durch ʿAṭf mit dem Akkusativ ‚Himmel‘ verbunden, also Akkusativ mit Fatḥa", "Subjekt von ‚umfasst‘ im Nominativ", "Mit einem Genitiv verbunden, also Genitiv", "Ḫabar eines neuen Satzes im Nominativ"], "Das Verb ‚umfasst‘ hat ein Subjekt und nimmt ‚die Himmel‘ als Objekt. Die Konjunktion wa- fügt ein zweites Objekt hinzu. ‚Himmel‘ ist ein gesunder femininer Plural mit Kasra im Akkusativ; dieses Wort, ein Singular, zeigt Fatḥa."],
    ar: ["الكلمة المظللة تلي واو العطف بعد «السماوات». ما إعرابها؟", ["معطوف على المنصوب «السماوات» فهو منصوب وعلامة نصبه الفتحة", "فاعل للفعل «وسع» مرفوع", "معطوف على مجرور فهو مجرور", "خبر لجملة جديدة مرفوع"], "للفعل فاعل ومفعول هو «السماوات»، والواو تعطف مفعولًا ثانيًا عليه. و«السماوات» جمع مؤنث سالم منصوب بالكسرة، أما هذه الكلمة فمفردة تُنصب بالفتحة."] },

  { id: "nhi-045", s: "nahw", g: 2, d: 3, t: ["past-verb", "mabni-muarab"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on mabnī and muʿrab", v: "1:7", w: 3,
    en: ["The highlighted verb ends with the subject pronoun ‘ta’ (you). What is the verb and what is the position of the ‘ta’?", ["A perfect verb built on sukūn; the ‘ta’ is the fāʿil, in the position of a nominative", "A perfect verb built on fatḥa; the ‘ta’ is the mafʿūl, in the position of an accusative", "An imperfect verb in the nominative; the ‘ta’ is a letter of prefix", "A perfect verb built on ḍamma; the ‘ta’ is the muḍāf ilayhi"], "When a movable subject pronoun is attached to a perfect, the verb is built on sukūn. The ‘ta’ of the second person is the subject, mabnī, in the position of a nominative. The object is the following attached pronoun ‘them’ introduced by ʿalā."],
    de: ["Das markierte Verb endet auf das Subjektpronomen ‚ta‘ (2. Person). Was ist das Verb und welche Stellung hat das ‚ta‘?", ["Ein auf Sukūn gebautes Perfekt; das ‚ta‘ ist das Fāʿil an der Stelle eines Nominativs", "Ein auf Fatḥa gebautes Perfekt; das ‚ta‘ ist das Mafʿūl an der Stelle eines Akkusativs", "Ein Imperfekt im Nominativ; das ‚ta‘ ist ein Präfixbuchstabe", "Ein auf Ḍamma gebautes Perfekt; das ‚ta‘ ist das Muḍāf ilayhi"], "Wird an ein Perfekt ein bewegliches Subjektpronomen angehängt, ist das Verb auf Sukūn gebaut. Das ‚ta‘ der zweiten Person ist das Subjekt, mabnī, an der Stelle eines Nominativs. Das Objekt ist das folgende, mit ʿalā eingeleitete Pronomen ‚sie‘."],
    ar: ["الفعل المظلل اتصلت به تاء الفاعل. ما إعراب الفعل ومحل التاء؟", ["فعل ماض مبني على السكون والتاء ضمير مبني في محل رفع فاعل", "فعل ماض مبني على الفتح والتاء ضمير في محل نصب مفعول به", "فعل مضارع مرفوع والتاء حرف مضارعة", "فعل ماض مبني على الضم والتاء مضاف إليه"], "إذا اتصل بالماضي ضمير رفع متحرك بُني على السكون، وتاء المخاطب ضمير مبني في محل رفع فاعل."] },

  { id: "nhi-046", s: "nahw", g: 1, d: 1, t: ["fail", "irab-case"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the fāʿil", v: "2:285", w: 2,
    en: ["The verb at the start of the verse is a perfect verb. What is the highlighted word that follows it?", ["The fāʿil, nominative with ḍamma", "The mafʿūl bihi, accusative", "The khabar of a nominal sentence", "The muḍāf ilayhi, genitive"], "A verb is followed by its doer, always marfūʿ. The word is the one who believed, a definite noun with ḍamma."],
    de: ["Das Verb am Anfang des Verses ist ein Perfekt. Was ist das darauffolgende markierte Wort?", ["Das Fāʿil im Nominativ mit Ḍamma", "Das Mafʿūl bihi im Akkusativ", "Das Ḫabar eines Nominalsatzes", "Das Muḍāf ilayhi im Genitiv"], "Auf ein Verb folgt sein Handelnder, immer im Nominativ. Das Wort ist derjenige, der glaubte, ein bestimmtes Nomen mit Ḍamma."],
    ar: ["الفعل في أول الآية فعل ماض. ما إعراب الكلمة المظللة بعده؟", ["فاعل مرفوع وعلامة رفعه الضمة", "مفعول به منصوب", "خبر في جملة اسمية", "مضاف إليه مجرور"], "يأتي بعد الفعل فاعله وهو مرفوع دائمًا، وهنا اسم معرّف مرفوع بالضمة."] },

  { id: "nhi-047", s: "nahw", g: 1, d: 1, t: ["mafulat", "maful-bihi"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the accusative nouns", v: "2:286", w: 4,
    en: ["The verb ‘burdens’ has God as its subject. What is the highlighted word?", ["The first direct object, accusative with tanwīn fatḥa", "The fāʿil, nominative", "The khabar of inna", "The ḥāl, accusative"], "‘Burdens’ takes two objects in this construction: the person burdened and the thing laid on them. The highlighted word is the first, manṣūb and indefinite."],
    de: ["Das Verb ‚belastet‘ hat Gott als Subjekt. Was ist das markierte Wort?", ["Das erste direkte Objekt im Akkusativ mit Tanwīn-Fatḥa", "Das Fāʿil im Nominativ", "Das Ḫabar von inna", "Der Ḥāl im Akkusativ"], "‚Belastet‘ hat in dieser Konstruktion zwei Objekte: die belastete Person und das Auferlegte. Das markierte Wort ist das erste, manṣūb und unbestimmt."],
    ar: ["الفعل «يكلّف» فاعله لفظ الجلالة. ما إعراب الكلمة المظللة؟", ["مفعول به أول منصوب وعلامة نصبه الفتحة (تنوين الفتح)", "فاعل مرفوع", "خبر «إنّ»", "حال منصوبة"], "يتعدّى «كلّف» هنا إلى مفعولين: المكلَّف والمكلَّف به، والكلمة المظللة الأول منصوبة نكرة."] },

  { id: "nhi-048", s: "nahw", g: 1, d: 1, t: ["past-verb", "mabni-muarab"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the perfect verb", v: "110:1", w: 2,
    en: ["On what is the highlighted perfect verb built, with no pronoun attached to it?", ["Fatḥa", "Sukūn", "Ḍamma", "Kasra"], "A perfect verb with nothing attached (or with the dual alif or the feminine tāʾ) is built on fatḥa. Sukūn comes with movable subject pronouns, ḍamma with wāw."],
    de: ["Worauf ist das markierte Perfekt gebaut, wenn kein Pronomen angehängt ist?", ["Auf Fatḥa", "Auf Sukūn", "Auf Ḍamma", "Auf Kasra"], "Ein Perfekt ohne Anhängsel (oder mit Dual-Alif bzw. femininem Tāʾ) ist auf Fatḥa gebaut. Sukūn steht bei beweglichen Subjektpronomen, Ḍamma bei Wāw."],
    ar: ["على م يُبنى الفعل الماضي المظلل وهو غير متصل بضمير؟", ["على الفتح", "على السكون", "على الضم", "على الكسر"], "الماضي الخالي من الضمائر (أو المتصل بألف الاثنين أو تاء التأنيث) مبني على الفتح، ويُبنى على السكون مع ضمائر الرفع المتحركة وعلى الضم مع واو الجماعة."] },

  { id: "nhi-049", s: "nahw", g: 1, d: 1, t: ["mudaf-ilayhi", "irab-case"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the genitive nouns", v: "3:185", w: 4,
    en: ["The preceding word, ‘one that tastes’, is a khabar annexed to the highlighted word. What is the highlighted word?", ["Muḍāf ilayhi, genitive with kasra", "Fāʿil, nominative", "Mafʿūl bihi, accusative", "Mubtadaʾ, nominative"], "The active participle ‘tasting’ is annexed to what is tasted, an annexation of a participle to its object. The second term of any annexation is genitive."],
    de: ["Das vorangehende Wort ‚Kostende‘ ist ein mit dem markierten Wort verbundenes Ḫabar. Was ist das markierte Wort?", ["Muḍāf ilayhi im Genitiv mit Kasra", "Fāʿil im Nominativ", "Mafʿūl bihi im Akkusativ", "Mubtadaʾ im Nominativ"], "Das Partizip ‚kostend‘ ist mit dem Gekosteten verbunden, eine Verbindung eines Partizips mit seinem Objekt. Das zweite Glied jeder Iḍāfa steht im Genitiv."],
    ar: ["الكلمة قبل المظللة هي خبر مضاف، وهي «ذائقة». ما إعراب الكلمة المظللة؟", ["مضاف إليه مجرور وعلامة جرّه الكسرة", "فاعل مرفوع", "مفعول به منصوب", "مبتدأ مرفوع"], "اسم الفاعل «ذائقة» مضاف إلى مفعوله، والمضاف إليه مجرور دائمًا."] },

  { id: "nhi-050", s: "nahw", g: 2, d: 3, t: ["sound-feminine-plural", "mafulat"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the signs of i‘rāb", v: "6:1", w: 5,
    en: ["The highlighted word is the object of the verb ‘created’ and is a sound feminine plural. What is its sign?", ["Kasra, in place of fatḥa", "Fatḥa", "Yāʾ", "Alif"], "In the accusative the sound feminine plural takes kasra instead of fatḥa. Yāʾ is for the sound masculine plural and the dual; alif is for the nominative dual."],
    de: ["Das markierte Wort ist das Objekt des Verbs ‚erschuf‘ und ein gesunder femininer Plural. Was ist sein Zeichen?", ["Kasra anstelle von Fatḥa", "Fatḥa", "Yāʾ", "Alif"], "Im Akkusativ hat der gesunde feminine Plural Kasra statt Fatḥa. Yāʾ gehört zum gesunden maskulinen Plural und zum Dual, Alif zum Nominativ des Duals."],
    ar: ["الكلمة المظللة مفعول به للفعل «خلق» وهي جمع مؤنث سالم. ما علامة نصبها؟", ["الكسرة نيابة عن الفتحة", "الفتحة", "الياء", "الألف"], "جمع المؤنث السالم يُنصب بالكسرة نيابة عن الفتحة، أما الياء فلجمع المذكر السالم والمثنى والألف لرفع المثنى."] },

  // ---------- Stage 3 (secondary) ----------
  { id: "nhi-051", s: "nahw", g: 3, d: 3, t: ["nafiya-lil-jins", "la-negation"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on lā that negates the genus (lā al-nāfiya lil-jins)", v: "2:2", w: 3,
    en: ["What kind of particle is the highlighted lā, which stands before an indefinite singular noun in the accusative position?", ["Lā al-nāfiya lil-jins, negating the whole class and acting like inna", "Lā al-nāhiya, a prohibition that jussives the verb", "Lā al-zāʾida, a particle with no function", "Lā that negates the present like laysa, with a nominative ism"], "The particle before an indefinite singular noun built on fatḥa, with no tanwīn, is lā of absolute negation of the genus. It works like inna: it gives its ism the accusative position and leaves the khabar nominative."],
    de: ["Um welche Art Partikel handelt es sich bei dem markierten lā vor einem unbestimmten Singularnomen an Akkusativstelle?", ["Lā al-nāfiya lil-ǧins, das die ganze Gattung verneint und wie inna wirkt", "Lā al-nāhiya, ein Verbot, das das Verb in den Jussiv setzt", "Lā al-zāʾida, eine Partikel ohne Funktion", "Ein lā, das wie laysa die Gegenwart verneint, mit einem Ism im Nominativ"], "Die Partikel vor einem unbestimmten Singularnomen, das auf Fatḥa gebaut ist und kein Tanwīn trägt, ist das lā der absoluten Gattungsverneinung. Es wirkt wie inna: Sein Ism erhält die Akkusativstelle, das Ḫabar bleibt im Nominativ."],
    ar: ["ما نوع «لا» المظللة التي دخلت على اسم نكرة مفرد في محل نصب؟", ["لا النافية للجنس تعمل عمل «إنّ»", "لا الناهية تجزم الفعل", "لا الزائدة لا عمل لها", "لا النافية العاملة عمل «ليس» واسمها مرفوع"], "«لا» التي تدخل على نكرة مفردة مبنية على الفتح بلا تنوين هي النافية للجنس، تعمل عمل «إنّ» فتنصب الاسم محلًّا وترفع الخبر."] },

  { id: "nhi-052", s: "nahw", g: 3, d: 3, t: ["nafiya-lil-jins", "mabni-muarab"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on lā that negates the genus", v: "2:2", w: 4,
    en: ["What is the highlighted noun, which comes directly after the negating particle?", ["The ism of lā, built on fatḥa in the position of an accusative", "The khabar of lā, nominative", "A mubtadaʾ, nominative with ḍamma", "A mafʿūl bihi, accusative with a visible fatḥa"], "After lā of genus negation, a singular noun (neither annexed nor resembling an annexation) is built on fatḥa without tanwīn. The fatḥa is a sign of building, not of case, and the position is accusative. The khabar is the following prepositional phrase."],
    de: ["Was ist das markierte Nomen, das unmittelbar auf die Verneinungspartikel folgt?", ["Das Ism von lā, auf Fatḥa gebaut an der Stelle eines Akkusativs", "Das Ḫabar von lā im Nominativ", "Ein Mubtadaʾ im Nominativ mit Ḍamma", "Ein Mafʿūl bihi im Akkusativ mit sichtbarer Fatḥa"], "Nach dem lā der Gattungsverneinung ist ein Singularnomen (weder verbunden noch einer Verbindung ähnlich) ohne Tanwīn auf Fatḥa gebaut. Die Fatḥa ist hier Bauzeichen, nicht Kasuszeichen, und die Stelle ist Akkusativ. Das Ḫabar ist die folgende Präpositionalgruppe."],
    ar: ["ما إعراب الاسم المظلل الذي يلي حرف النفي مباشرة؟", ["اسم «لا» مبني على الفتح في محل نصب", "خبر «لا» مرفوع", "مبتدأ مرفوع بالضمة", "مفعول به منصوب بفتحة ظاهرة"], "الاسم المفرد (غير المضاف وغير الشبيه به) بعد «لا» النافية للجنس يُبنى على الفتح بلا تنوين، والفتحة بناء لا إعراب، ومحله النصب. وخبرها الجار والمجرور بعده."] },

  { id: "nhi-053", s: "nahw", g: 3, d: 3, t: ["munada", "mabni-muarab"], src: "Ibn Hishām, Qaṭr al-Nadā, chapter on the vocative (al-munādā)", v: "2:21", w: 1,
    en: ["In the vocative ‘yā ayyuhā’, what is ‘ayyu’ and what is ‘hā’?", ["‘Ayyu’ is the munādā, built on ḍamma in the position of an accusative; ‘hā’ is a particle of attention (tanbīh)", "‘Ayyu’ is a mubtadaʾ; ‘hā’ is its khabar", "‘Ayyu’ is a fāʿil; ‘hā’ is a pronoun in the genitive", "‘Ayyu’ is a particle; ‘hā’ is the munādā"], "A definite noun cannot be called directly with yā, so ‘ayyu’ serves as a bridge: it is the real munādā (a single word, built on ḍamma) and ‘hā’ is the particle of attention. The word that follows is its description."],
    de: ["Was sind im Vokativ ‚yā ayyuhā‘ das ‚ayyu‘ und das ‚hā‘?", ["‚Ayyu‘ ist der Munādā, auf Ḍamma gebaut an der Stelle eines Akkusativs; ‚hā‘ ist eine Aufmerksamkeitspartikel (Tanbīh)", "‚Ayyu‘ ist ein Mubtadaʾ; ‚hā‘ sein Ḫabar", "‚Ayyu‘ ist ein Fāʿil; ‚hā‘ ein Pronomen im Genitiv", "‚Ayyu‘ ist eine Partikel; ‚hā‘ der Munādā"], "Ein bestimmtes Nomen kann nicht unmittelbar mit yā angerufen werden, daher dient ‚ayyu‘ als Brücke: Es ist der eigentliche Munādā (ein einzelnes Wort, auf Ḍamma gebaut), und ‚hā‘ ist die Aufmerksamkeitspartikel. Das folgende Wort ist seine Beschreibung."],
    ar: ["ما إعراب «أيّ» و«ها» في النداء «يا أيها»؟", ["«أيّ» منادى مبني على الضم في محل نصب، و«ها» حرف تنبيه", "«أيّ» مبتدأ و«ها» خبر", "«أيّ» فاعل و«ها» ضمير في محل جر", "«أيّ» حرف و«ها» منادى"], "لا يُنادى المعرّف بـ«أل» مباشرة بـ«يا»، فيُتوصل بـ«أيّ» وهي المنادى المبني على الضم في محل نصب، و«ها» للتنبيه، والاسم بعدها صفة لها."] },

  { id: "nhi-054", s: "nahw", g: 3, d: 3, t: ["ism-fail", "mafulat"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the active participle (ismu al-fāʿil)", v: "2:30", w: 6,
    en: ["The highlighted word is an active participle with tanwīn after inna. What is its role and what does it govern?", ["Khabar of inna, nominative; it governs the following noun as its object", "Ism of inna, accusative; it has no object", "Fāʿil, nominative; it governs a ḥāl", "Muḍāf ilayhi, genitive; it governs a verb"], "The participle is the khabar of inna and keeps its verbal power because it indicates the present or future and has tanwīn: it can take an object (‘one who will place …’). Its object here is the accusative noun at the end of the clause."],
    de: ["Das markierte Wort ist ein Partizip Aktiv mit Tanwīn nach inna. Welche Rolle hat es und was regiert es?", ["Ḫabar von inna im Nominativ; es regiert das folgende Nomen als sein Objekt", "Ism von inna im Akkusativ; es hat kein Objekt", "Fāʿil im Nominativ; es regiert einen Ḥāl", "Muḍāf ilayhi im Genitiv; es regiert ein Verb"], "Das Partizip ist das Ḫabar von inna und behält seine verbale Kraft, weil es Gegenwart oder Zukunft anzeigt und Tanwīn trägt: Es kann ein Objekt nehmen (‚einer, der einsetzen wird …‘). Sein Objekt ist hier das Nomen im Akkusativ am Ende des Satzes."],
    ar: ["الكلمة المظللة اسم فاعل منوّن بعد «إنّ». ما وظيفتها وماذا تعمل؟", ["خبر «إنّ» مرفوع، وتعمل عمل فعلها فتنصب المفعول به", "اسم «إنّ» منصوب ولا مفعول لها", "فاعل مرفوع تعمل في حال", "مضاف إليه مجرور تعمل في فعل"], "اسم الفاعل هنا خبر «إنّ»، ويعمل عمل فعله لأنه بمعنى الحال أو الاستقبال ومنوّن، فينصب المفعول به وهو آخر الجملة."] },

  { id: "nhi-055", s: "nahw", g: 3, d: 3, t: ["istithna", "mansubat"], src: "Ibn Hishām, Awḍaḥ al-Masālik, chapter on the exception (al-istithnāʾ)", v: "2:34", w: 8,
    en: ["Why must the highlighted noun after illā be accusative in the verse shown?", ["Because the sentence before illā is complete and affirmative, so the excepted noun is obligatorily accusative", "Because it is the object of the verb ‘prostrated’", "Because illā is always followed by an accusative, in every sentence", "Because it is a vocative"], "In a complete affirmative sentence (the excepted-from group is mentioned and no negation precedes), the noun after illā takes the accusative as mustathnā. After a negative sentence a nominative substitute is allowed. This noun also has no tanwīn, being a non-Arabic name."],
    de: ["Warum muss das markierte Nomen nach illā im gezeigten Vers im Akkusativ stehen?", ["Weil der Satz vor illā vollständig und bejaht ist, sodass das Ausgenommene zwingend im Akkusativ steht", "Weil es das Objekt des Verbs ‚sie warfen sich nieder‘ ist", "Weil auf illā immer ein Akkusativ folgt, in jedem Satz", "Weil es ein Vokativ ist"], "In einem vollständigen bejahten Satz (die Gruppe, aus der ausgenommen wird, ist genannt, keine Negation geht voraus) steht das Nomen nach illā als Mustaṯnā im Akkusativ. Nach einem verneinten Satz ist ein Nominativ-Ersatz erlaubt. Dieses Nomen trägt zudem kein Tanwīn, da es ein nichtarabischer Name ist."],
    ar: ["لماذا يجب نصب الاسم المظلل بعد «إلا» في الآية المعروضة؟", ["لأن الكلام قبل «إلا» تام موجب فيجب نصب المستثنى", "لأنه مفعول به للفعل «سجدوا»", "لأن ما بعد «إلا» منصوب في كل جملة", "لأنه منادى"], "إذا كان الكلام تامًّا موجبًا (ذُكر المستثنى منه ولم يسبقه نفي) وجب نصب المستثنى بعد «إلا»، أما بعد النفي فيجوز الإبدال. والاسم هنا ممنوع من الصرف لأنه أعجمي."] },

  { id: "nhi-056", s: "nahw", g: 3, d: 3, t: ["mamnu-min-sarf", "irab-markers"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the signs of i‘rāb (the diptote)", v: "2:34", w: 5,
    en: ["The highlighted name follows the preposition lām and is a non-Arabic proper name, a diptote. What is its sign?", ["Fatḥa in place of kasra, with no tanwīn", "Kasra with tanwīn", "Kasra without tanwīn", "Yāʾ, as in a sound masculine plural"], "A diptote (mamnūʿ min al-ṣarf) takes fatḥa instead of kasra in the genitive and has no tanwīn, unless it is annexed or has al-. Non-Arabic proper names are among the causes of this restriction."],
    de: ["Der markierte Name folgt der Präposition lām und ist ein nichtarabischer Eigenname, ein Diptotum. Was ist sein Zeichen?", ["Fatḥa anstelle von Kasra, ohne Tanwīn", "Kasra mit Tanwīn", "Kasra ohne Tanwīn", "Yāʾ wie beim gesunden maskulinen Plural"], "Ein Diptotum (Mamnūʿ min aṣ-ṣarf) hat im Genitiv Fatḥa statt Kasra und kein Tanwīn, es sei denn, es ist verbunden oder hat al-. Nichtarabische Eigennamen gehören zu den Ursachen dieser Einschränkung."],
    ar: ["الاسم المظلل علم أعجمي بعد لام الجر وهو ممنوع من الصرف. ما علامة جرّه؟", ["الفتحة نيابة عن الكسرة بلا تنوين", "الكسرة مع التنوين", "الكسرة بلا تنوين", "الياء كجمع المذكر السالم"], "الممنوع من الصرف يُجرّ بالفتحة نيابة عن الكسرة ولا يُنوَّن ما لم يضف أو تدخل عليه «أل»، والعلم الأعجمي من علل المنع."] },

  { id: "nhi-057", s: "nahw", g: 3, d: 3, t: ["past-verb", "muqaddar-markers"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the verb ending in a weak letter", v: "2:34", w: 9,
    en: ["The highlighted perfect verb ends in alif maqṣūra. How is its building shown?", ["Built on an implied fatḥa on the final alif", "Built on a visible fatḥa", "Built on sukūn", "Built on the omission of the final letter"], "A perfect verb is built on fatḥa, but the alif cannot take a vowel, so the fatḥa is only implied (muqaddar) there, hindered by the impossibility of pronouncing it."],
    de: ["Das markierte Perfekt endet auf Alif maqṣūra. Wie zeigt sich sein Bau?", ["Gebaut auf einer gedachten Fatḥa auf dem letzten Alif", "Gebaut auf einer sichtbaren Fatḥa", "Gebaut auf Sukūn", "Gebaut auf dem Wegfall des letzten Buchstabens"], "Ein Perfekt ist auf Fatḥa gebaut, doch das Alif kann keinen Vokal tragen, daher ist die Fatḥa dort nur gedacht (muqaddar), verhindert durch die Unmöglichkeit der Aussprache."],
    ar: ["الفعل الماضي المظلل ينتهي بألف مقصورة. كيف يُعرب بناؤه؟", ["مبني على فتح مقدر على الألف منع من ظهوره التعذر", "مبني على فتح ظاهر", "مبني على السكون", "مبني على حذف آخره"], "الماضي مبني على الفتح، وإذا كان آخره ألفًا قُدّر الفتح عليها للتعذر لأن الألف لا تقبل الحركة."] },

  { id: "nhi-058", s: "nahw", g: 3, d: 3, t: ["nahi", "afal-khamsa"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the jussive (jawāzim al-muḍāriʿ)", v: "2:60", w: 25,
    en: ["The highlighted verb follows lā in a prohibition. What is its state and sign?", ["Jussive (majzūm) by lā al-nāhiya, with the omission of the final nūn", "Nominative, with the nūn kept", "Subjunctive by an implied an, with fatḥa", "Built on sukūn like an imperative"], "Lā of prohibition puts the imperfect in the jussive. This verb is one of the five verbs, whose sign of jussive is the loss of the nūn; the wāw is the subject."],
    de: ["Das markierte Verb folgt in einem Verbot auf lā. Welchen Zustand und welches Zeichen hat es?", ["Jussiv (majzūm) durch lā al-nāhiya, mit Wegfall des letzten Nūn", "Nominativ mit erhaltenem Nūn", "Subjunktiv durch ein ergänztes an, mit Fatḥa", "Auf Sukūn gebaut wie ein Imperativ"], "Das lā des Verbots setzt das Imperfekt in den Jussiv. Dieses Verb gehört zu den fünf Verben, deren Jussivzeichen der Wegfall des Nūn ist; das Wāw ist das Subjekt."],
    ar: ["الفعل المظلل جاء بعد «لا» في النهي. ما حالته وعلامتها؟", ["مضارع مجزوم بـ«لا» الناهية وعلامة جزمه حذف النون", "مضارع مرفوع وعلامة رفعه ثبوت النون", "مضارع منصوب بـ«أن» مضمرة وعلامة نصبه الفتحة", "فعل مبني على السكون كالأمر"], "«لا» الناهية تجزم المضارع، وهذا الفعل من الأفعال الخمسة وعلامة جزمه حذف النون، والواو فاعل."] },

  { id: "nhi-059", s: "nahw", g: 3, d: 4, t: ["hal-tamyiz", "hal"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the ḥāl (the confirming ḥāl)", v: "2:60", w: 28,
    en: ["The highlighted word describes a state of those addressed whose meaning is already implied by the verb before it. What is it called?", ["Ḥāl muʾakkida (a confirming circumstantial accusative)", "Tamyīz", "Mafʿūl lahu", "Naʿt maqṭūʿ"], "The verb already means ‘to spread corruption’, so the participle that follows it adds nothing new but reinforces: a ḥāl muʾakkida for its verb. It is accusative with yāʾ as a sound masculine plural."],
    de: ["Das markierte Wort beschreibt einen Zustand der Angesprochenen, dessen Bedeutung im vorangehenden Verb schon enthalten ist. Wie heißt es?", ["Ḥāl muʾakkida (bekräftigender Zustandsakkusativ)", "Tamyīz", "Mafʿūl lahu", "Naʿt maqṭūʿ"], "Das Verb bedeutet schon ‚Unheil stiften‘, das folgende Partizip fügt also nichts Neues hinzu, sondern verstärkt: ein Ḥāl muʾakkida für sein Verb. Es steht im Akkusativ mit Yāʾ als gesunder maskuliner Plural."],
    ar: ["الكلمة المظللة تصف هيئة المخاطبين ومعناها مفهوم من الفعل قبلها. ماذا يسمى هذا النوع؟", ["حال مؤكِّدة", "تمييز", "مفعول لأجله", "نعت مقطوع"], "الفعل «تعثوا» معناه الإفساد، فالكلمة بعده لا تضيف جديدًا بل تؤكد معنى عاملها، فهي حال مؤكدة منصوبة بالياء."] },

  { id: "nhi-060", s: "nahw", g: 3, d: 3, t: ["nafiya-lil-jins", "mabni-muarab"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on lā that negates the genus", v: "2:197", w: 9,
    en: ["In the reading of Ḥafṣ the highlighted word has a plain fatḥa and no tanwīn. What is the best explanation?", ["It is the ism of lā al-nāfiya lil-jins, built on fatḥa", "It is a manṣūb object of the verb before it", "It is a mubtadaʾ in the accusative", "It is a diptote in the genitive"], "The fatḥa and the absence of tanwīn show the ism of lā of genus negation, built on fatḥa. In some other readings the first nouns of the series are marfūʿ with tanwīn, which changes the analysis."],
    de: ["In der Lesart von Ḥafṣ trägt das markierte Wort eine einfache Fatḥa ohne Tanwīn. Was ist die beste Erklärung?", ["Es ist das Ism von lā al-nāfiya lil-ǧins, auf Fatḥa gebaut", "Es ist ein Akkusativobjekt des vorangehenden Verbs", "Es ist ein Mubtadaʾ im Akkusativ", "Es ist ein Diptotum im Genitiv"], "Die Fatḥa und das Fehlen von Tanwīn zeigen das Ism von lā der Gattungsverneinung, auf Fatḥa gebaut. In einigen anderen Lesarten stehen die ersten Nomen der Reihe im Nominativ mit Tanwīn, was die Analyse ändert."],
    ar: ["في رواية حفص تظهر على الكلمة المظللة فتحة بلا تنوين. ما أحسن تفسير ذلك؟", ["هي اسم «لا» النافية للجنس مبني على الفتح", "هي مفعول به منصوب للفعل قبلها", "هي مبتدأ منصوب", "هي ممنوعة من الصرف مجرورة"], "الفتحة وعدم التنوين تدلان على اسم «لا» النافية للجنس المبني على الفتح. وفي بعض القراءات الأخرى يُرفع أول الألفاظ منونًا فيتغير التحليل."] },

  { id: "nhi-061", s: "nahw", g: 3, d: 3, t: ["shart", "jazm-nasb"], src: "Ibn Hishām, Awḍaḥ al-Masālik, chapter on the conditional particles (jawāzim)", v: "2:197", w: 17,
    en: ["The highlighted verb follows the particle that begins a conditional clause (‘whatever you do …’). What is its state?", ["Jussive (majzūm) as the verb of the condition, with the nūn dropped", "Nominative with the nūn kept", "Subjunctive by an", "Built on fatḥa as a perfect"], "‘Mā’ here is a conditional noun and jussives two verbs, the condition and its answer. This verb is the condition; as one of the five verbs it is jussive by loss of the nūn, and the answer is the next verb."],
    de: ["Das markierte Verb folgt der Partikel, die einen Bedingungssatz einleitet (‚was immer ihr tut …‘). Welchen Zustand hat es?", ["Jussiv (majzūm) als Verb der Bedingung, mit Wegfall des Nūn", "Nominativ mit erhaltenem Nūn", "Subjunktiv durch an", "Auf Fatḥa gebaut als Perfekt"], "Mā ist hier ein Bedingungsnomen und setzt zwei Verben in den Jussiv, die Bedingung und ihre Antwort. Dieses Verb ist die Bedingung; als eines der fünf Verben ist es durch Wegfall des Nūn im Jussiv, die Antwort ist das nächste Verb."],
    ar: ["الفعل المظلل جاء بعد أداة تبدأ جملة شرط («وما تفعلوا ...»). ما حالته؟", ["فعل الشرط مجزوم وعلامة جزمه حذف النون", "مرفوع بثبوت النون", "منصوب بـ«أن»", "فعل ماض مبني على الفتح"], "«ما» هنا اسم شرط جازم يجزم فعلين: فعل الشرط وجوابه. وهذا فعل الشرط، وهو من الأفعال الخمسة فجزمه بحذف النون، وجوابه الفعل التالي."] },

  { id: "nhi-062", s: "nahw", g: 3, d: 3, t: ["mansub-lan", "afal-khamsa"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the subjunctive (nawāṣib)", v: "3:92", w: 2,
    en: ["The verb after lan is one of the five verbs. How is it put into the subjunctive?", ["By dropping the final nūn; the wāw is the subject", "By a fatḥa on the last letter", "By a sukūn on the last letter", "By keeping the nūn"], "Lan puts an imperfect into the subjunctive. For the five verbs the sign of the subjunctive is the loss of the nūn, the same as for the jussive."],
    de: ["Das Verb nach lan gehört zu den fünf Verben. Wie wird es in den Subjunktiv gesetzt?", ["Durch Wegfall des letzten Nūn; das Wāw ist das Subjekt", "Durch eine Fatḥa auf dem letzten Buchstaben", "Durch ein Sukūn auf dem letzten Buchstaben", "Durch Beibehaltung des Nūn"], "Lan setzt ein Imperfekt in den Subjunktiv. Bei den fünf Verben ist das Zeichen des Subjunktivs der Wegfall des Nūn, genau wie beim Jussiv."],
    ar: ["الفعل بعد «لن» من الأفعال الخمسة. كيف يُنصب؟", ["بحذف النون والواو فاعل", "بفتحة على آخره", "بسكون على آخره", "بثبوت النون"], "«لن» حرف نصب للمضارع، والأفعال الخمسة تُنصب بحذف النون كما تُجزم بحذفها."] },

  { id: "nhi-063", s: "nahw", g: 3, d: 3, t: ["shart", "jazm-nasb"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the conditional particles", v: "4:123", w: 8,
    en: ["In the clause ‘Whoever does evil …’, what is the highlighted verb?", ["The verb of the condition, jussive with sukūn, after the conditional noun man", "The answer, nominative with ḍamma", "A relative clause, nominative", "A perfect built on fatḥa"], "Man here is conditional and jussives two verbs. This is the condition (jussive with sukūn) and the next verb is the answer, also jussive. If man were a relative pronoun the verb would be nominative."],
    de: ["Was ist das markierte Verb in der Wendung ‚Wer Böses tut …‘?", ["Das Verb der Bedingung, Jussiv mit Sukūn, nach dem Bedingungsnomen man", "Die Antwort im Nominativ mit Ḍamma", "Ein Relativsatz im Nominativ", "Ein auf Fatḥa gebautes Perfekt"], "Man ist hier konditional und setzt zwei Verben in den Jussiv. Dies ist die Bedingung (Jussiv mit Sukūn), das nächste Verb ist die Antwort, ebenfalls im Jussiv. Wäre man ein Relativpronomen, stünde das Verb im Nominativ."],
    ar: ["ما إعراب الفعل المظلل في «من يعمل سوءًا ...»؟", ["فعل الشرط مضارع مجزوم وعلامة جزمه السكون بعد اسم الشرط «من»", "جواب الشرط مرفوع بالضمة", "صلة موصول مرفوعة", "فعل ماض مبني على الفتح"], "«من» هنا شرطية جازمة تجزم فعلين، وهذا فعل الشرط مجزوم بالسكون والفعل التالي جوابه. ولو كانت «من» اسمًا موصولًا لكان الفعل مرفوعًا."] },

  { id: "nhi-064", s: "nahw", g: 3, d: 3, t: ["mafulat", "maful-mutlaq"], src: "Ibn Hishām, Awḍaḥ al-Masālik, chapter on the absolute object (al-mafʿūl al-muṭlaq)", v: "4:164", w: 14,
    en: ["The highlighted verbal noun repeats the meaning of the verb before it to emphasise it. What is it?", ["Mafʿūl muṭlaq (absolute object), accusative", "Mafʿūl lahu", "Ḥāl", "Tamyīz"], "A masdar of the same root as the verb, put after it to give emphasis, is a mafʿūl muṭlaq. It is manṣūb. The emphasis here denies any metaphorical reading of the speaking."],
    de: ["Das markierte Verbalnomen wiederholt die Bedeutung des vorangehenden Verbs zur Betonung. Was ist es?", ["Mafʿūl muṭlaq (absolutes Objekt), Akkusativ", "Mafʿūl lahu", "Ḥāl", "Tamyīz"], "Ein Maṣdar derselben Wurzel wie das Verb, nachgestellt zur Betonung, ist ein Mafʿūl muṭlaq. Er ist manṣūb. Die Betonung schließt hier ein übertragenes Verständnis des Sprechens aus."],
    ar: ["المصدر المظلل يكرر معنى الفعل قبله للتوكيد. ما إعرابه؟", ["مفعول مطلق منصوب", "مفعول لأجله", "حال", "تمييز"], "المصدر من لفظ الفعل إذا جاء بعده للتوكيد فهو مفعول مطلق منصوب، وهنا يدفع احتمال المجاز في الكلام."] },

  { id: "nhi-065", s: "nahw", g: 3, d: 4, t: ["munada", "attached-pronouns"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the vocative annexed to the speaker's yāʾ", v: "12:4", w: 5,
    en: ["The highlighted word is a vocative meaning ‘my father’ and ends in tāʾ. What does this tāʾ stand for?", ["It replaces the speaker's yāʾ (‘my’); the word is an annexed munādā, accusative", "It marks the feminine; the word is a feminine noun", "It is the pronoun ‘you’ in the genitive", "It is a dual ending; the word is a mubtadaʾ"], "When a child calls a parent, the yāʾ of the speaker (‘my’) can be replaced by tāʾ, which is why the word keeps a masculine sense although it ends in tāʾ. The noun is a muḍāf munādā and therefore manṣūb."],
    de: ["Das markierte Wort ist ein Vokativ mit der Bedeutung ‚mein Vater‘ und endet auf Tāʾ. Wofür steht dieses Tāʾ?", ["Es ersetzt das Yāʾ des Sprechers (‚mein‘); das Wort ist ein verbundener Munādā im Akkusativ", "Es kennzeichnet das Femininum; das Wort ist ein feminines Nomen", "Es ist das Pronomen der 2. Person im Genitiv", "Es ist eine Dualendung; das Wort ist ein Mubtadaʾ"], "Wenn ein Kind seine Eltern anruft, kann das Yāʾ des Sprechers (‚mein‘) durch Tāʾ ersetzt werden; deshalb behält das Wort einen maskulinen Sinn, obwohl es auf Tāʾ endet. Das Nomen ist ein Muḍāf-Munādā und daher manṣūb."],
    ar: ["الكلمة المظللة منادى بمعنى «أبي» وتنتهي بتاء. ماذا تمثل هذه التاء؟", ["عوض عن ياء المتكلم والكلمة منادى مضاف منصوب", "علامة تأنيث والكلمة اسم مؤنث", "ضمير المخاطب في محل جر", "علامة تثنية والكلمة مبتدأ"], "إذا نادى الابن أباه جاز تعويض ياء المتكلم بالتاء، ولذلك يبقى المعنى مذكرًا مع ختم الكلمة بالتاء، والمنادى المضاف منصوب."] },

  { id: "nhi-066", s: "nahw", g: 3, d: 3, t: ["hal-tamyiz", "tamyiz"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the number and the tamyīz", v: "12:4", w: 10,
    en: ["The highlighted word explains the number ‘eleven’. What is it?", ["Tamyīz (specifier), singular accusative", "Ḥāl, accusative", "Mafʿūl lahu", "Khabar of inna"], "After the numbers 11 to 99 the counted noun is a singular indefinite accusative, called tamyīz, which removes the vagueness of the number."],
    de: ["Das markierte Wort erklärt die Zahl ‚elf‘. Was ist es?", ["Tamyīz (Spezifizierer), Singular im Akkusativ", "Ḥāl im Akkusativ", "Mafʿūl lahu", "Ḫabar von inna"], "Nach den Zahlen 11 bis 99 steht das Gezählte als unbestimmter Singular im Akkusativ, genannt Tamyīz, der die Unbestimmtheit der Zahl aufhebt."],
    ar: ["الكلمة المظللة تفسّر العدد «أحد عشر». ما إعرابها؟", ["تمييز منصوب مفرد", "حال منصوبة", "مفعول لأجله", "خبر «إنّ»"], "بعد الأعداد من أحد عشر إلى تسعة وتسعين يأتي المعدود مفردًا نكرة منصوبًا ويسمى تمييزًا لأنه يزيل إبهام العدد."] },

  { id: "nhi-067", s: "nahw", g: 3, d: 3, t: ["tawabi", "tawkid"], src: "Ibn Ājurrūm, al-Ājurrūmiyya, chapter on the tawkīd", v: "15:30", w: 3,
    en: ["The highlighted word, ‘all of them’, repeats the meaning of ‘the angels’ for emphasis. What is it?", ["Tawkīd (emphasis), nominative, following the word it emphasises", "A khabar, nominative", "A ḥāl, accusative", "A tamyīz, accusative"], "‘Kull’ annexed to a pronoun that refers back to the emphasised word is a tawkīd maʿnawī, a follower of the fāʿil in the nominative. The next word is a further tawkīd."],
    de: ["Das markierte Wort ‚alle von ihnen‘ wiederholt zur Betonung die Bedeutung von ‚die Engel‘. Was ist es?", ["Tawkīd (Betonung) im Nominativ, dem betonten Wort folgend", "Ein Ḫabar im Nominativ", "Ein Ḥāl im Akkusativ", "Ein Tamyīz im Akkusativ"], "‚Kull‘, mit einem auf das betonte Wort zurückweisenden Pronomen verbunden, ist ein Tawkīd maʿnawī, ein Folgewort des Fāʿil im Nominativ. Das nächste Wort ist ein weiterer Tawkīd."],
    ar: ["الكلمة المظللة «كلهم» تكرر معنى «الملائكة» للتوكيد. ما إعرابها؟", ["توكيد معنوي مرفوع تبعًا للمؤكَّد", "خبر مرفوع", "حال منصوبة", "تمييز منصوب"], "«كل» المضافة إلى ضمير يعود على المؤكَّد توكيد معنوي، وتتبع الفاعل في الرفع، والكلمة بعدها توكيد آخر."] },

  { id: "nhi-068", s: "nahw", g: 3, d: 3, t: ["zarf", "mansubat"], src: "Ibn Hishām, Awḍaḥ al-Masālik, chapter on the adverb (al-mafʿūl fīhi)", v: "17:1", w: 5,
    en: ["The highlighted word says when the journey took place. What is it?", ["Ẓarf zamān (adverb of time), accusative, attached to the verb", "Mafʿūl bihi, accusative", "Fāʿil, nominative", "Muḍāf ilayhi, genitive"], "A noun that answers ‘when?’ and implies the preposition ‘in’ is a mafʿūl fīhi (ẓarf), always manṣūb. The word is indefinite, which also hints at the shortness of the journey."],
    de: ["Das markierte Wort nennt die Zeit der Reise. Was ist es?", ["Ẓarf zamān (Zeitadverb), Akkusativ, am Verb hängend", "Mafʿūl bihi im Akkusativ", "Fāʿil im Nominativ", "Muḍāf ilayhi im Genitiv"], "Ein Nomen, das auf ‚wann?‘ antwortet und die Präposition ‚in‘ einschließt, ist ein Mafʿūl fīhi (Ẓarf), immer manṣūb. Das Wort ist unbestimmt, was auch auf die Kürze der Reise hindeutet."],
    ar: ["الكلمة المظللة تبيّن زمن الرحلة. ما إعرابها؟", ["ظرف زمان منصوب متعلق بالفعل", "مفعول به منصوب", "فاعل مرفوع", "مضاف إليه مجرور"], "الاسم الذي يجيب عن «متى» ويتضمن معنى «في» يسمى مفعولًا فيه (ظرفًا) وهو منصوب، وتنكيره يشير إلى قصر المدة."] },

  { id: "nhi-069", s: "nahw", g: 3, d: 4, t: ["hal-tamyiz", "tamyiz"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the tamyīz (al-tamyīz al-muḥawwal)", v: "19:4", w: 9,
    en: ["The highlighted word explains in what respect the head burned. How is it classified?", ["Tamyīz muḥawwal ʿan al-fāʿil (the specifier converted from the subject)", "Ḥāl of the head", "Tamyīz of a number", "Mafʿūl muṭlaq"], "The meaning is ‘the grey of the head blazed’: the original subject (grey hair) has been turned into a tamyīz, accusative, and the original subject word has become the fāʿil. This is called a converted tamyīz."],
    de: ["Das markierte Wort erklärt, in welcher Hinsicht der Kopf brannte. Wie wird es eingeordnet?", ["Tamyīz muḥawwal ʿan al-fāʿil (aus dem Subjekt umgewandelter Spezifizierer)", "Ḥāl des Kopfes", "Tamyīz einer Zahl", "Mafʿūl muṭlaq"], "Gemeint ist ‚das Grau des Kopfes loderte auf‘: Das ursprüngliche Subjekt (graues Haar) wurde zu einem Tamyīz im Akkusativ, und das ursprüngliche Subjektwort wurde zum Fāʿil. Das heißt umgewandelter Tamyīz."],
    ar: ["الكلمة المظللة تبيّن الجهة التي اشتعل فيها الرأس. كيف تُصنَّف؟", ["تمييز محوّل عن الفاعل", "حال من الرأس", "تمييز عدد", "مفعول مطلق"], "الأصل «اشتعل شيب الرأس»، فحُوّل الفاعل (شيب) إلى تمييز منصوب وصار المضاف إليه (الرأس) فاعلًا، وهذا هو التمييز المحوّل عن الفاعل."] },

  { id: "nhi-070", s: "nahw", g: 3, d: 3, t: ["mafulat", "maful-lahu"], src: "Ibn Hishām, Awḍaḥ al-Masālik, chapter on the object of purpose (al-mafʿūl lahu)", v: "2:19", w: 15,
    en: ["The highlighted word gives the reason for putting their fingers in their ears. What is it?", ["Mafʿūl lahu (object of purpose), accusative", "Mafʿūl muṭlaq", "Ẓarf makān", "Khabar of kāna"], "A verbal noun that states why an action is done, shares its time and doer with the verb, and is not a verb, is a mafʿūl lahu (li-ajlihi), manṣūb. The word is annexed to ‘death’."],
    de: ["Das markierte Wort nennt den Grund dafür, dass sie ihre Finger in die Ohren stecken. Was ist es?", ["Mafʿūl lahu (Zweckobjekt), Akkusativ", "Mafʿūl muṭlaq", "Ẓarf makān", "Ḫabar von kāna"], "Ein Verbalnomen, das den Grund einer Handlung nennt, Zeit und Handelnden mit dem Verb teilt und kein Verb ist, ist ein Mafʿūl lahu (li-aǧlihi), manṣūb. Das Wort ist mit ‚Tod‘ verbunden."],
    ar: ["الكلمة المظللة تذكر سبب وضع الأصابع في الآذان. ما إعرابها؟", ["مفعول لأجله منصوب", "مفعول مطلق", "ظرف مكان", "خبر «كان»"], "المصدر الذي يبيّن علة الفعل ويتفق مع فعله في الزمان والفاعل هو المفعول لأجله، وهو منصوب، وقد أُضيف هنا إلى «الموت»."] },

  { id: "nhi-071", s: "nahw", g: 3, d: 3, t: ["idafa", "jar-wa-majrur"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the annexation (al-iḍāfa)", v: "55:13", w: 1,
    en: ["The highlighted word is the interrogative noun ‘which’ preceded by the preposition bi-. What is its case?", ["Genitive, by the preposition; it is also annexed to the next word", "Accusative, because it is a question word", "Nominative, because it starts the clause", "Built on sukūn in the position of an accusative"], "‘Ayy’ is declinable. It is majrūr here by the preposition and is the muḍāf of the following noun. Most interrogative words are mabnī, but ‘ayy’ is an exception because of its annexation."],
    de: ["Das markierte Wort ist das Fragenomen ‚welche‘ mit der Präposition bi-. Welchen Kasus hat es?", ["Genitiv durch die Präposition; es ist zugleich mit dem nächsten Wort verbunden", "Akkusativ, weil es ein Fragewort ist", "Nominativ, weil es den Satz eröffnet", "Auf Sukūn gebaut an der Stelle eines Akkusativs"], "‚Ayy‘ ist deklinierbar. Hier steht es durch die Präposition im Genitiv und ist das Muḍāf des folgenden Nomens. Die meisten Fragewörter sind mabnī, ‚ayy‘ ist wegen seiner Verbindung eine Ausnahme."],
    ar: ["الكلمة المظللة اسم الاستفهام «أيّ» مسبوق بالباء. ما حالتها؟", ["اسم مجرور بالباء وهو مضاف إلى ما بعده", "منصوب لأنه اسم استفهام", "مرفوع لأنه بداية الجملة", "مبني على السكون في محل نصب"], "«أيّ» معربة، وهي هنا مجرورة بالباء ومضافة إلى الاسم بعدها. أكثر أسماء الاستفهام مبنية لكن «أيّ» تُعرب بسبب إضافتها."] },

  { id: "nhi-072", s: "nahw", g: 3, d: 4, t: ["inna-sisters", "kafa"], src: "Ibn Hishām, Mughnī al-Labīb, on innamā; Ibn ʿAqīl, Sharḥ Alfiyya, chapter on inna and mā", v: "4:171", w: 14,
    en: ["The word after innamā is nominative. Why is it not accusative as the ism of inna?", ["Because mā is kāffa (restraining): it stops inna from governing, so the word is a mubtadaʾ", "Because it is a vocative", "Because it is the khabar of kāna", "Because inna has been omitted"], "When mā is attached to inna it normally cancels its government, so the clause becomes an ordinary nominal sentence. The word is the mubtadaʾ in the nominative, and its khabar follows."],
    de: ["Das Wort nach innamā steht im Nominativ. Warum nicht im Akkusativ als Ism von inna?", ["Weil mā kāffa (hemmend) ist: Es hindert inna am Regieren, das Wort ist also ein Mubtadaʾ", "Weil es ein Vokativ ist", "Weil es das Ḫabar von kāna ist", "Weil inna ausgelassen wurde"], "Hängt sich mā an inna, hebt es in der Regel deren Rektion auf, und der Satz wird ein gewöhnlicher Nominalsatz. Das Wort ist das Mubtadaʾ im Nominativ, das Ḫabar folgt."],
    ar: ["الكلمة بعد «إنما» مرفوعة. لماذا لم تُنصب اسمًا لـ«إنّ»؟", ["لأن «ما» كافة تكف «إنّ» عن العمل فالكلمة مبتدأ", "لأنها منادى", "لأنها خبر «كان»", "لأن «إنّ» محذوفة"], "إذا اتصلت «ما» بـ«إنّ» كفّتها عن العمل فصارت الجملة اسمية عادية، والكلمة مبتدأ مرفوع وخبره بعده."] },

  { id: "nhi-073", s: "nahw", g: 3, d: 4, t: ["tawabi", "attached-pronouns"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the lām of the khabar (lām al-ibtidāʾ)", v: "103:2", w: 3,
    en: ["The highlighted word begins with a lām before the khabar of inna. What is this lām called and what does it do?", ["Lām al-ibtidāʾ (the displaced lām, muzaḥlaqa), giving emphasis, moved from the mubtadaʾ to the khabar", "Lām al-jarr, a preposition of ownership", "Lām al-amr, a command lām", "Lām al-taʿlīl, a lām of purpose"], "Because inna and lām both give emphasis, the two cannot stand together. The lām of the mubtadaʾ is moved to the khabar and called muzaḥlaqa (the slid one). Here the khabar is a prepositional phrase."],
    de: ["Das markierte Wort beginnt mit einem Lām vor dem Ḫabar von inna. Wie heißt dieses Lām und was bewirkt es?", ["Lām al-ibtidāʾ (das verschobene Lām, muzaḥlaqa), das betont und vom Mubtadaʾ zum Ḫabar verschoben ist", "Lām al-ǧarr, eine Präposition des Besitzes", "Lām al-amr, ein Befehls-Lām", "Lām al-taʿlīl, ein Lām des Zwecks"], "Da inna und Lām beide betonen, können sie nicht nebeneinanderstehen. Das Lām des Mubtadaʾ wird zum Ḫabar verschoben und heißt Muzaḥlaqa (das Gerutschte). Das Ḫabar ist hier eine Präpositionalgruppe."],
    ar: ["الكلمة المظللة تبدأ بلام قبل خبر «إنّ». ما اسم هذه اللام ووظيفتها؟", ["لام الابتداء المزحلقة للتوكيد انتقلت من المبتدأ إلى الخبر", "لام الجر للملك", "لام الأمر", "لام التعليل"], "لما كان لـ«إنّ» واللام معنى التوكيد لم يجتمعا في صدر الجملة، فزُحلقت لام الابتداء إلى الخبر، وسُميت المزحلقة. والخبر هنا شبه جملة."] },

  { id: "nhi-074", s: "nahw", g: 3, d: 4, t: ["istithna", "mansubat"], src: "Ibn Hishām, Awḍaḥ al-Masālik, chapter on the exception", v: "103:3", w: 2,
    en: ["The group introduced by illā is excepted from the human being, which is generic. How is the relative pronoun analysed?", ["As the excepted noun, in the position of an accusative", "As the subject of a verb, nominative", "As a muḍāf ilayhi, genitive", "As a vocative"], "The relative pronoun is mabnī and stands in the position of the accusative as mustathnā. The human being is taken in the sense of a class, so the exception removes the believers who do righteous deeds from the loss."],
    de: ["Die mit illā eingeleitete Gruppe wird aus dem Menschen ausgenommen, der hier als Gattung steht. Wie wird das Relativpronomen analysiert?", ["Als das Ausgenommene (Mustaṯnā) an der Stelle eines Akkusativs", "Als Subjekt eines Verbs im Nominativ", "Als Muḍāf ilayhi im Genitiv", "Als Vokativ"], "Das Relativpronomen ist mabnī und steht an der Stelle eines Akkusativs als Mustaṯnā. Der Mensch ist im Sinn einer Gattung gemeint, sodass die Ausnahme die Gläubigen, die Gutes tun, vom Verlust ausnimmt."],
    ar: ["الجملة المستثناة بـ«إلا» مستثناة من «الإنسان» وهو اسم جنس. ما إعراب الاسم الموصول؟", ["مستثنى في محل نصب", "فاعل في محل رفع", "مضاف إليه في محل جر", "منادى"], "الاسم الموصول مبني في محل نصب على الاستثناء، و«الإنسان» اسم جنس بمعنى الجمع، فالاستثناء يخرج المؤمنين العاملين من الخسران."] },

  { id: "nhi-075", s: "nahw", g: 3, d: 3, t: ["jazm-nasb", "weak-verbs"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the jussive of the defective verb", v: "105:1", w: 2,
    en: ["The highlighted verb ‘see’ follows lam. How is the jussive shown?", ["By dropping the final weak letter (ḥadhf ḥarf al-ʿilla)", "By a sukūn on the last letter", "By dropping the nūn", "By fatḥa"], "A verb ending in a weak letter is jussive by dropping the weak letter, here the final alif (the previous vowel remains as a clue). Sukūn is for sound verbs and loss of the nūn for the five verbs."],
    de: ["Das markierte Verb ‚sehen‘ folgt auf lam. Wie zeigt sich der Jussiv?", ["Durch Wegfall des letzten schwachen Buchstabens (ḥaḏf ḥarf al-ʿilla)", "Durch ein Sukūn auf dem letzten Buchstaben", "Durch Wegfall des Nūn", "Durch Fatḥa"], "Ein Verb mit schwachem Endbuchstaben steht im Jussiv durch Wegfall dieses Buchstabens, hier des letzten Alif (der Vokal davor bleibt als Hinweis). Sukūn gilt für gesunde Verben, der Wegfall des Nūn für die fünf Verben."],
    ar: ["الفعل المظلل «ترى» مسبوق بـ«لم». كيف يظهر جزمه؟", ["بحذف حرف العلة من آخره", "بسكون على آخره", "بحذف النون", "بالفتحة"], "الفعل المعتل الآخر يُجزم بحذف حرف العلة، وهنا الألف، أما السكون فللصحيح وحذف النون للأفعال الخمسة."] },

  { id: "nhi-076", s: "nahw", g: 3, d: 4, t: ["mafulat", "word-order"], src: "Ibn Hishām, Mughnī al-Labīb, on ammā; Ibn ʿAqīl, Sharḥ Alfiyya, chapter on fronting the object", v: "93:9", w: 2,
    en: ["The highlighted word is placed before a verb that governs it. What is its role?", ["Mafʿūl bihi of the verb that follows, brought forward, accusative", "Mubtadaʾ of a nominal sentence", "Fāʿil of the verb that follows", "Muḍāf ilayhi"], "In ammā constructions an element must follow ammā, so the object of the verb is moved forward in front of it. It is manṣūb by the verb that comes after the fāʾ."],
    de: ["Das markierte Wort steht vor einem Verb, das es regiert. Welche Rolle hat es?", ["Mafʿūl bihi des folgenden Verbs, vorangestellt, Akkusativ", "Mubtadaʾ eines Nominalsatzes", "Fāʿil des folgenden Verbs", "Muḍāf ilayhi"], "In Konstruktionen mit ammā muss ein Element auf ammā folgen, daher wird das Objekt des Verbs davor nach vorn gezogen. Es ist manṣūb durch das Verb, das nach dem Fāʾ steht."],
    ar: ["الكلمة المظللة تقدمت على فعل يعمل فيها. ما وظيفتها؟", ["مفعول به مقدّم للفعل بعدها منصوب", "مبتدأ لجملة اسمية", "فاعل للفعل بعدها", "مضاف إليه"], "في أسلوب «أمّا» يجب أن يليها شيء من الجملة، فقُدّم المفعول به على فعله، وهو منصوب بالفعل الذي بعد الفاء."] },

  { id: "nhi-077", s: "nahw", g: 3, d: 4, t: ["pronouns", "mubtada-khabar"], src: "Ibn Hishām, Mughnī al-Labīb, on the pronoun of separation", v: "2:5", w: 7,
    en: ["The pronoun between the mubtadaʾ and its definite khabar is called what, and what does it do?", ["Ḍamīr al-faṣl: it separates khabar from adjective and adds emphasis", "Ḍamīr al-shaʾn: it replaces a subject", "Ḍamīr mustatir: it is a hidden subject", "Ḍamīr muttaṣil: it completes the verb"], "A pronoun of the third person placed between a mubtadaʾ and a definite khabar is called faṣl: it makes clear that what follows is a khabar and not a description, and adds restriction. Basran grammarians say it has no i‘rāb position."],
    de: ["Wie heißt das Pronomen zwischen dem Mubtadaʾ und seinem bestimmten Ḫabar, und was bewirkt es?", ["Ḍamīr al-faṣl: Es trennt Ḫabar und Adjektiv und verstärkt", "Ḍamīr al-šaʾn: Es ersetzt ein Subjekt", "Ḍamīr mustatir: Es ist ein verborgenes Subjekt", "Ḍamīr muttaṣil: Es vervollständigt das Verb"], "Ein Pronomen der dritten Person zwischen einem Mubtadaʾ und einem bestimmten Ḫabar heißt Faṣl: Es macht deutlich, dass das Folgende ein Ḫabar und keine Beschreibung ist, und fügt Beschränkung hinzu. Nach Ansicht der Basrer hat es keine Stellung im Iʿrāb."],
    ar: ["ما اسم الضمير الواقع بين المبتدأ وخبره المعرّف، وما فائدته؟", ["ضمير الفصل يفصل بين الخبر والنعت ويفيد التوكيد", "ضمير الشأن يقوم مقام المبتدأ", "ضمير مستتر فاعل", "ضمير متصل يكمل الفعل"], "ضمير الغائب بين المبتدأ والخبر المعرفة يسمى ضمير فصل، يُبيّن أن ما بعده خبر لا نعت ويفيد الحصر والتوكيد، ولا محل له من الإعراب عند البصريين."] },

  { id: "nhi-078", s: "nahw", g: 3, d: 4, t: ["hadhf", "mafulat"], src: "al-Zamakhsharī, al-Kashshāf, on 12:82; Ibn Hishām, Mughnī al-Labīb, on ḥadhf al-muḍāf", v: "12:82", w: 2,
    en: ["Literally the accusative object is a town, but the meaning is its inhabitants. How is this analysed?", ["As mafʿūl bihi with an understood muḍāf (‘the people of’) that has been dropped", "As ẓarf makān, the place of questioning", "As a ḥāl", "As a muḍāf ilayhi"], "Grammarians explain that a muḍāf is omitted (ḥadhf al-muḍāf) and the muḍāf ilayhi takes its place in the accusative: ‘ask the people of the town’. This is figurative speech, not asking the stones."],
    de: ["Wörtlich ist das Akkusativobjekt eine Stadt, gemeint sind aber ihre Bewohner. Wie wird das analysiert?", ["Als Mafʿūl bihi mit ausgelassenem Muḍāf (‚die Leute von‘), das weggefallen ist", "Als Ẓarf makān, der Ort der Befragung", "Als Ḥāl", "Als Muḍāf ilayhi"], "Die Grammatiker erklären, dass ein Muḍāf ausgelassen ist (ḥaḏf al-muḍāf) und das Muḍāf ilayhi an seiner Stelle im Akkusativ steht: ‚frage die Leute der Stadt‘. Das ist bildliche Rede, nicht das Befragen der Steine."],
    ar: ["المفعول به المنصوب في ظاهره «قرية» والمراد أهلها. كيف يُحلَّل؟", ["مفعول به على حذف مضاف تقديره «أهل»", "ظرف مكان للسؤال", "حال", "مضاف إليه"], "يقول النحاة بحذف المضاف وإقامة المضاف إليه مقامه في النصب: «واسأل أهل القرية»، وهذا من المجاز الذي يُحمل على الحذف."] },

  { id: "nhi-079", s: "nahw", g: 3, d: 4, t: ["mamnu-min-sarf", "irab-markers"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the diptote (mā lā yanṣarif)", v: "2:124", w: 3,
    en: ["The highlighted word is a non-Arabic proper name that is the object of the verb. What are its case and sign?", ["Accusative with fatḥa and no tanwīn, as a diptote", "Accusative with tanwīn fatḥa", "Nominative with ḍamma", "Genitive with kasra"], "As an accusative object it is manṣūb; the fatḥa without tanwīn shows that the name does not take tanwīn (diptote: foreign proper name). It is placed before the subject because of the pronoun in the subject."],
    de: ["Das markierte Wort ist ein nichtarabischer Eigenname und Objekt des Verbs. Was sind Kasus und Zeichen?", ["Akkusativ mit Fatḥa ohne Tanwīn, als Diptotum", "Akkusativ mit Tanwīn-Fatḥa", "Nominativ mit Ḍamma", "Genitiv mit Kasra"], "Als Akkusativobjekt ist es manṣūb; die Fatḥa ohne Tanwīn zeigt, dass der Name kein Tanwīn nimmt (Diptotum: fremder Eigenname). Es steht wegen des Pronomens im Subjekt vor diesem."],
    ar: ["الكلمة المظللة علم أعجمي وقعت مفعولًا به. ما حالتها وعلامتها؟", ["مفعول به منصوب وعلامة نصبه الفتحة ممنوع من الصرف", "مفعول به منصوب بتنوين الفتح", "فاعل مرفوع بالضمة", "مجرور بالكسرة"], "هو مفعول به منصوب بالفتحة بلا تنوين لأنه ممنوع من الصرف (علم أعجمي)، وقد تقدم على الفاعل لاتصال الفاعل بضمير يعود عليه."] },

  { id: "nhi-080", s: "nahw", g: 3, d: 3, t: ["munada", "mabni-muarab"], src: "Ibn Hishām, Qaṭr al-Nadā, chapter on the vocative (the word Allāhumma)", v: "3:26", w: 2,
    en: ["What is the mīm at the end of the highlighted word and what is the word as a whole?", ["The doubled mīm stands in for the particle yā; the word is a munādā built on an implied ḍamma", "The mīm is a dual marker; the word is a mubtadaʾ", "The mīm is a pronoun in the genitive; the word is a muḍāf", "The mīm is a letter of prefix; the word is a verb"], "According to the Basrans, the doubled mīm replaces the particle of calling yā, so the two never stand together; the word is a munādā mufrad, built on an implied ḍamma, in the position of an accusative."],
    de: ["Was ist das Mīm am Ende des markierten Wortes und was ist das Wort insgesamt?", ["Das verdoppelte Mīm vertritt die Partikel yā; das Wort ist ein Munādā, auf gedachter Ḍamma gebaut", "Das Mīm ist ein Dualzeichen; das Wort ist ein Mubtadaʾ", "Das Mīm ist ein Pronomen im Genitiv; das Wort ist ein Muḍāf", "Das Mīm ist ein Präfixbuchstabe; das Wort ist ein Verb"], "Nach den Basrern ersetzt das verdoppelte Mīm die Anrufpartikel yā, beide stehen nie zusammen; das Wort ist ein einzelner Munādā, auf gedachter Ḍamma gebaut, an der Stelle eines Akkusativs."],
    ar: ["ما الميم المشددة في آخر الكلمة المظللة وما إعرابها؟", ["الميم عوض عن حرف النداء «يا» والكلمة منادى مبني على ضم مقدر", "الميم علامة تثنية والكلمة مبتدأ", "الميم ضمير في محل جر والكلمة مضاف", "الميم حرف مضارعة والكلمة فعل"], "عند البصريين الميم المشددة عوض عن «يا» النداء ولذلك لا يجتمعان، والكلمة منادى مفرد مبني على ضم مقدر في محل نصب."] },

  // ---------- Stage 4 (university) ----------
  { id: "nhi-081", s: "nahw", g: 4, d: 4, t: ["hal-tamyiz", "hal"], src: "al-Zamakhsharī, al-Kashshāf, on the beginning of al-Baqara; Ibn Hishām, Mughnī al-Labīb", v: "2:2", w: 6,
    en: ["Which statement gives a recognised analysis of the highlighted word?", ["A ḥāl from ‘the Book’ (or from the pronoun in the prepositional phrase), with the case sign implied on the final alif", "A tamyīz specifying the preceding negated noun", "A mafʿūl muṭlaq of an omitted verb", "A muḍāf ilayhi of the prepositional phrase before it"], "Commentators and grammarians analyse the word as a circumstantial accusative (ḥāl) of the Book, while others take it as a second khabar or as the khabar of an omitted mubtadaʾ. In all cases it ends in alif maqṣūra, so the sign is only implied. It is not a tamyīz, since nothing before it needs specifying."],
    de: ["Welche Aussage gibt eine anerkannte Analyse des markierten Wortes wieder?", ["Ein Ḥāl von ‚dem Buch‘ (oder vom Pronomen in der Präpositionalgruppe), mit gedachtem Zeichen auf dem letzten Alif", "Ein Tamyīz, der das vorangehende verneinte Nomen spezifiziert", "Ein Mafʿūl muṭlaq eines ausgelassenen Verbs", "Ein Muḍāf ilayhi der davorstehenden Präpositionalgruppe"], "Kommentatoren und Grammatiker analysieren das Wort als Zustandsakkusativ (Ḥāl) des Buches, andere nehmen es als zweites Ḫabar oder als Ḫabar eines ausgelassenen Mubtadaʾ. In allen Fällen endet es auf Alif maqṣūra, das Zeichen ist also nur gedacht. Ein Tamyīz ist es nicht, da davor nichts zu spezifizieren ist."],
    ar: ["أي العبارات الآتية تذكر وجهًا معتمدًا في إعراب الكلمة المظللة؟", ["حال من «الكتاب» (أو من الضمير في الجار والمجرور) وعلامتها مقدرة على الألف", "تمييز للاسم المنفي قبلها", "مفعول مطلق لفعل محذوف", "مضاف إليه للجار والمجرور قبلها"], "أعربها المفسرون والنحاة حالًا من «الكتاب»، وأجاز آخرون كونها خبرًا ثانيًا أو خبرًا لمبتدأ محذوف. وهي على كل الوجوه مقصورة فعلامتها مقدّرة. وليست تمييزًا إذ لا إبهام قبلها."] },

  { id: "nhi-082", s: "nahw", g: 4, d: 4, t: ["word-order", "mafulat"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the fāʿil (the cases of obligatory fronting of the object)", v: "2:124", w: 3,
    en: ["Why must the object stand before the subject in the clause shown?", ["Because the subject carries a pronoun that refers back to the object, and the pronoun may not precede its referent", "Because the object is a proper name", "Because the verb is passive", "Because it is a diptote"], "When the fāʿil contains an attached pronoun that returns to the object, the object must be put first; otherwise the pronoun would refer to something not yet mentioned. Being a diptote or a name does not require fronting."],
    de: ["Warum muss das Objekt im gezeigten Satz vor dem Subjekt stehen?", ["Weil das Subjekt ein Pronomen trägt, das sich auf das Objekt zurückbezieht, und das Pronomen seinem Bezugswort nicht vorangehen darf", "Weil das Objekt ein Eigenname ist", "Weil das Verb passiv ist", "Weil es ein Diptotum ist"], "Enthält das Fāʿil ein angehängtes Pronomen, das sich auf das Objekt bezieht, muss das Objekt vorangestellt werden; sonst bezöge sich das Pronomen auf etwas noch nicht Genanntes. Dass es ein Diptotum oder ein Name ist, erfordert keine Voranstellung."],
    ar: ["لماذا وجب تقديم المفعول به على الفاعل في الجملة المعروضة؟", ["لأن الفاعل اتصل به ضمير يعود على المفعول به، ولا يعود الضمير على متأخر لفظًا ورتبة", "لأن المفعول علم", "لأن الفعل مبني للمجهول", "لأنه ممنوع من الصرف"], "إذا اتصل بالفاعل ضمير يعود على المفعول وجب تقديم المفعول، وإلا عاد الضمير على متأخر لفظًا ورتبة، أما كونه علمًا أو ممنوعًا من الصرف فلا يوجب التقديم."] },

  { id: "nhi-083", s: "nahw", g: 4, d: 4, t: ["muqaddar-markers", "attached-pronouns"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the noun annexed to the speaker's yāʾ", v: "2:124", w: 18,
    en: ["The highlighted word is nominative and is annexed to the speaker's yāʾ. How is its ḍamma shown?", ["As an implied ḍamma on the last letter, blocked by the kasra required before the yāʾ", "As a visible ḍamma", "As a yāʾ in place of ḍamma", "It has no case because the yāʾ makes it mabnī"], "A noun annexed to the speaker's yāʾ is declinable, but the letter before the yāʾ must carry kasra, so the case sign (here ḍamma) is only implied, prevented by the vowel that suits the yāʾ (ishtighāl al-maḥall bi-ḥarakat al-munāsaba)."],
    de: ["Das markierte Wort steht im Nominativ und ist mit dem Yāʾ des Sprechers verbunden. Wie zeigt sich seine Ḍamma?", ["Als gedachte Ḍamma auf dem letzten Buchstaben, verdrängt von der vor dem Yāʾ nötigen Kasra", "Als sichtbare Ḍamma", "Als Yāʾ anstelle der Ḍamma", "Es hat keinen Kasus, weil das Yāʾ es mabnī macht"], "Ein mit dem Yāʾ des Sprechers verbundenes Nomen bleibt deklinierbar, aber der Buchstabe vor dem Yāʾ muss Kasra tragen, daher wird das Kasuszeichen (hier Ḍamma) nur gedacht, verhindert durch den zum Yāʾ passenden Vokal (ištiġāl al-maḥall bi-ḥarakat al-munāsaba)."],
    ar: ["الكلمة المظللة مرفوعة ومضافة إلى ياء المتكلم. كيف تظهر ضمتها؟", ["ضمة مقدرة على آخرها منع من ظهورها اشتغال المحل بحركة المناسبة", "ضمة ظاهرة", "ياء بدل الضمة", "لا إعراب لها لأن الياء تبنيها"], "الاسم المضاف إلى ياء المتكلم معرب، لكن ما قبل الياء يجب أن يُكسر، فتقدَّر علامة الإعراب (الضمة هنا) منعًا لظهورها اشتغال المحل بحركة المناسبة."] },

  { id: "nhi-084", s: "nahw", g: 4, d: 5, t: ["nafiya-lil-jins", "qiraat-nahw"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on lā; Ibn Hishām, Mughnī al-Labīb, on lā", v: "2:38", w: 13,
    en: ["In the reading of Ḥafṣ this noun has ḍamma with tanwīn after lā. How is it analysed?", ["As a mubtadaʾ in the nominative (with lā not the genus-negating one), whose khabar is the prepositional phrase", "As the ism of lā al-nāfiya lil-jins, built on fatḥa", "As a fāʿil of an omitted verb", "As a mafʿūl bihi, accusative"], "The genus-negating lā requires an ism built on fatḥa without tanwīn. Ḍamma with tanwīn shows that the noun is a mubtadaʾ after a negative lā (which some grammarians let work like laysa and others treat as non-working), with the prepositional phrase as khabar. Readers who build it on fatḥa have the other analysis."],
    de: ["In der Lesart von Ḥafṣ trägt dieses Nomen nach lā Ḍamma mit Tanwīn. Wie wird es analysiert?", ["Als Mubtadaʾ im Nominativ (mit einem lā, das nicht das gattungsverneinende ist), dessen Ḫabar die Präpositionalgruppe ist", "Als Ism von lā al-nāfiya lil-ǧins, auf Fatḥa gebaut", "Als Fāʿil eines ausgelassenen Verbs", "Als Mafʿūl bihi im Akkusativ"], "Das gattungsverneinende lā verlangt ein Ism, das auf Fatḥa ohne Tanwīn gebaut ist. Ḍamma mit Tanwīn zeigt, dass das Nomen ein Mubtadaʾ nach einem verneinenden lā ist (das manche Grammatiker wie laysa wirken lassen, andere als nicht wirkend ansehen), mit der Präpositionalgruppe als Ḫabar. Leser, die es auf Fatḥa bauen, haben die andere Analyse."],
    ar: ["في رواية حفص جاءت هذه الكلمة بضمة وتنوين بعد «لا». كيف تُحلَّل؟", ["مبتدأ مرفوع و«لا» ليست النافية للجنس، وخبره شبه الجملة", "اسم «لا» النافية للجنس مبني على الفتح", "فاعل لفعل محذوف", "مفعول به منصوب"], "«لا» النافية للجنس تقتضي اسمًا مبنيًّا على الفتح بلا تنوين، والضمة مع التنوين تدل على مبتدأ بعد «لا» النافية (التي أعملها بعضهم عمل ليس وأهملها آخرون)، وخبره الجار والمجرور. ومن قرأ بالفتح فله التحليل الآخر."] },

  { id: "nhi-085", s: "nahw", g: 4, d: 4, t: ["kana-sisters", "qiraat-nahw"], src: "al-Zamakhsharī, al-Kashshāf, on 2:177; Ibn ʿAqīl, Sharḥ Alfiyya, chapter on laysa", v: "2:177", w: 2,
    en: ["In the reading of Ḥafṣ this noun is accusative after laysa. What is its role, and what is the subject of laysa?", ["Khabar of laysa, put first; the ism is the following clause ‘an’ plus the subjunctive, a verbal noun in the nominative", "Ism of laysa; the khabar is the following clause", "Mafʿūl bihi of the following verb; laysa has no ism", "Ḥāl; the ism of laysa is a hidden pronoun"], "In this reading (Ḥamza and Ḥafṣ) the accusative noun is the khabar fronted, and the ism of laysa is the verbal noun made by ‘an tuwallū’. Other readers make the noun nominative as the ism and the clause the khabar; both are grammatical."],
    de: ["In der Lesart von Ḥafṣ steht dieses Nomen nach laysa im Akkusativ. Welche Rolle hat es, und was ist das Subjekt von laysa?", ["Ḫabar von laysa, vorangestellt; das Ism ist der folgende Satz ‚an‘ plus Subjunktiv, ein Verbalnomen im Nominativ", "Ism von laysa; das Ḫabar ist der folgende Satz", "Mafʿūl bihi des folgenden Verbs; laysa hat kein Ism", "Ḥāl; das Ism von laysa ist ein verborgenes Pronomen"], "In dieser Lesart (Ḥamza und Ḥafṣ) ist das Akkusativnomen das vorangestellte Ḫabar, und das Ism von laysa ist das Verbalnomen aus ‚an tuwallū‘. Andere Leser machen das Nomen zum Ism im Nominativ und den Satz zum Ḫabar; beides ist grammatisch."],
    ar: ["في رواية حفص نُصبت هذه الكلمة بعد «ليس». ما وظيفتها وما اسم «ليس»؟", ["خبر «ليس» مقدّم، واسمها المصدر المؤول من «أن» والفعل المضارع", "اسم «ليس» والخبر الجملة بعدها", "مفعول به للفعل بعدها ولا اسم لـ«ليس»", "حال واسم «ليس» ضمير مستتر"], "على قراءة حمزة وحفص تكون الكلمة المنصوبة خبر «ليس» المقدم، واسمها المصدر المؤول من «أن توّلوا». وغيرهم يرفعون الكلمة اسمًا ويجعلون المصدر خبرًا، وكلاهما جائز."] },

  { id: "nhi-086", s: "nahw", g: 4, d: 4, t: ["hadhf", "mubtada-khabar"], src: "al-Zamakhsharī, al-Kashshāf, on 2:197; Ibn Hishām, Mughnī al-Labīb, on ḥadhf al-muḍāf", v: "2:197", w: 2,
    en: ["‘Ḥajj’ is an action, but the highlighted word names a period of time. How do the grammarians reconcile the sentence?", ["By an omitted muḍāf, such as ‘the time of Ḥajj is the months …’ or ‘Ḥajj takes place in the months …’", "By taking the word as an accusative adverb", "By taking the word as a vocative", "By saying that the khabar is the verb that follows"], "A nominal sentence needs the khabar to match the mubtadaʾ. Since an action cannot be identical to a time, a word like ‘time’ is understood before the subject or before the khabar. This is the standard ḥadhf al-muḍāf explanation."],
    de: ["‚Ḥaǧǧ‘ ist eine Handlung, das markierte Wort nennt aber einen Zeitraum. Wie lösen die Grammatiker den Satz auf?", ["Durch ein ausgelassenes Muḍāf, etwa ‚die Zeit des Ḥaǧǧ sind die Monate …‘ oder ‚der Ḥaǧǧ findet in den Monaten statt …‘", "Indem das Wort als Adverb im Akkusativ genommen wird", "Indem das Wort als Vokativ genommen wird", "Indem das folgende Verb als Ḫabar gilt"], "Im Nominalsatz muss das Ḫabar zum Mubtadaʾ passen. Da eine Handlung nicht mit einer Zeit identisch sein kann, wird ein Wort wie ‚Zeit‘ vor dem Subjekt oder vor dem Ḫabar ergänzt. Das ist die übliche Erklärung durch Ḥaḏf al-muḍāf."],
    ar: ["«الحج» فعل والكلمة المظللة اسم زمان. كيف يوفّق النحاة بين المبتدأ والخبر؟", ["بتقدير مضاف محذوف، نحو «وقت الحج أشهر» أو «الحج في أشهر»", "بجعل الكلمة ظرفًا منصوبًا", "بجعل الكلمة منادى", "بجعل الخبر الفعل بعدها"], "يشترط في الخبر أن يطابق المبتدأ في المعنى، ولا يكون الحدث زمانًا، فيُقدَّر مضاف قبل المبتدأ (وقت الحج) أو قبل الخبر (الحج حج أشهر). وهذا الحذف معروف في النحو."] },

  { id: "nhi-087", s: "nahw", g: 4, d: 4, t: ["istithna", "nafiya-lil-jins"], src: "Ibn Hishām, Mughnī al-Labīb, on illā and on the formula of tawḥīd", v: "2:255", w: 5,
    en: ["The statement is negative and the pronoun comes after illā. Which analysis of the highlighted pronoun is correct?", ["A badal from the position of lā and its ism (a nominative), the sentence being negative so a substitute is preferred", "A mustathnā that must be accusative, as the sentence is complete", "The khabar of lā, built on fatḥa", "A tawkīd of the ism of lā"], "After a complete negative sentence the excepted word is preferably a badal rather than an obligatory accusative. As the subject of lā + ism is in the position of a mubtadaʾ, the pronoun, which is mabnī, stands in the position of a nominative. Some grammarians prefer a badal from the pronoun in the omitted khabar."],
    de: ["Der Satz ist verneint und das Pronomen steht nach illā. Welche Analyse des markierten Pronomens trifft zu?", ["Ein Badal von der Stelle von lā und seinem Ism (ein Nominativ), da der Satz verneint ist und ein Ersatz bevorzugt wird", "Ein Mustaṯnā, das im Akkusativ stehen muss, da der Satz vollständig ist", "Das Ḫabar von lā, auf Fatḥa gebaut", "Ein Tawkīd des Ism von lā"], "Nach einem vollständigen verneinten Satz ist das Ausgenommene bevorzugt ein Badal und kein zwingender Akkusativ. Da das Subjekt aus lā + Ism an der Stelle eines Mubtadaʾ steht, steht das Pronomen, das mabnī ist, an der Stelle eines Nominativs. Manche Grammatiker bevorzugen ein Badal vom Pronomen im ausgelassenen Ḫabar."],
    ar: ["الجملة منفية وجاء الضمير بعد «إلا». أي تحليل للضمير المظلل صحيح؟", ["بدل من محل «لا» واسمها (في محل رفع) لأن الكلام منفي فالإبدال أولى", "مستثنى يجب نصبه لأن الكلام تام", "خبر «لا» مبني على الفتح", "توكيد لاسم «لا»"], "إذا كان الكلام تامًّا منفيًّا فالأرجح إبدال المستثنى لا وجوب نصبه. ومحل «لا» واسمها رفع بالابتداء، فالضمير المبني في محل رفع بدل منه. وبعضهم يجعله بدلًا من الضمير المستتر في الخبر المحذوف."] },

  { id: "nhi-088", s: "nahw", g: 4, d: 4, t: ["tanwin", "mubtada-khabar"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the types of tanwīn (tanwīn al-ʿiwaḍ)", v: "2:285", w: 9,
    en: ["The highlighted word is a mubtadaʾ with tanwīn although it is followed by a verb. What kind of tanwīn is this?", ["Tanwīn al-ʿiwaḍ, standing in for an omitted muḍāf ilayhi", "Tanwīn al-tamkīn (the ordinary sign of a fully declinable noun)", "Tanwīn al-tankīr (marking indefiniteness of an indeclinable word)", "Tanwīn al-muqābala (the sign of the sound feminine plural)"], "The word means ‘each of them’; the omitted muḍāf ilayhi (‘them’) is replaced by tanwīn. A word like ‘kull’ is normally annexed, so this tanwīn is a compensation. The khabar is the following verb."],
    de: ["Das markierte Wort ist ein Mubtadaʾ mit Tanwīn, obwohl ein Verb folgt. Welche Art von Tanwīn ist das?", ["Tanwīn al-ʿiwaḍ, das für ein ausgelassenes Muḍāf ilayhi steht", "Tanwīn al-tamkīn (das gewöhnliche Zeichen eines voll deklinierbaren Nomens)", "Tanwīn al-tankīr (Zeichen der Unbestimmtheit eines unveränderlichen Wortes)", "Tanwīn al-muqābala (das Zeichen des gesunden femininen Plurals)"], "Das Wort bedeutet ‚jeder von ihnen‘; das ausgelassene Muḍāf ilayhi (‚sie‘) wird durch Tanwīn ersetzt. Ein Wort wie ‚kull‘ wird normalerweise verbunden, daher ist dieses Tanwīn ein Ausgleich. Das Ḫabar ist das folgende Verb."],
    ar: ["الكلمة المظللة مبتدأ منوّن مع أن بعدها فعلًا. ما نوع هذا التنوين؟", ["تنوين العوض عن مضاف إليه محذوف", "تنوين التمكين", "تنوين التنكير", "تنوين المقابلة"], "المعنى «كلُّهم»، فعُوّض عن المضاف إليه المحذوف بالتنوين، لأن «كل» تلزمها الإضافة في الأصل. والخبر الفعل بعدها."] },

  { id: "nhi-089", s: "nahw", g: 4, d: 4, t: ["mansub-lan", "an-mudmara"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the particles of the subjunctive", v: "3:92", w: 5,
    en: ["What puts the highlighted verb, which follows ḥattā, into the subjunctive?", ["An understood an after ḥattā, with the nūn dropped", "The particle ḥattā itself", "The earlier lan in the verse, as the same clause", "The jussive that follows the conditional mā"], "Ḥattā is a preposition and cannot govern a verb; the subjunctive comes from an implied an (obligatory after ḥattā), forming a verbal noun that the preposition governs. The earlier lan governs the earlier verb only. The word is one of the five verbs, so the sign is the loss of the nūn."],
    de: ["Was setzt das markierte Verb, das auf ḥattā folgt, in den Subjunktiv?", ["Ein ergänztes an nach ḥattā, mit Wegfall des Nūn", "Die Partikel ḥattā selbst", "Das frühere lan im Vers, da es derselbe Satz ist", "Der Jussiv nach dem konditionalen mā"], "Ḥattā ist eine Präposition und kann kein Verb regieren; der Subjunktiv entsteht durch ein ergänztes an (nach ḥattā zwingend), das ein Verbalnomen bildet, das die Präposition regiert. Das frühere lan regiert nur das frühere Verb. Das Wort gehört zu den fünf Verben, das Zeichen ist daher der Wegfall des Nūn."],
    ar: ["ما الذي نصب الفعل المظلل الواقع بعد «حتى»؟", ["«أن» مضمرة وجوبًا بعد «حتى» وعلامة النصب حذف النون", "«حتى» نفسها", "«لن» السابقة في الآية", "«ما» الشرطية الجازمة"], "«حتى» حرف جر لا يعمل في الفعل، والنصب بـ«أن» مضمرة وجوبًا بعدها، وتكون مع الفعل مصدرًا مؤولًا مجرورًا بـ«حتى». و«لن» عملت في الفعل الأول فقط. والفعل من الأفعال الخمسة فعلامة نصبه حذف النون."] },

  { id: "nhi-090", s: "nahw", g: 4, d: 4, t: ["shart", "weak-verbs"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the jussive of defective verbs", v: "4:123", w: 10,
    en: ["The highlighted verb is the answer to the condition. What is its form?", ["Jussive passive, the final weak letter dropped as the sign of the jussive", "Nominative with an implied ḍamma on the final alif", "Subjunctive with an implied fatḥa", "Built on sukūn like a perfect"], "The answer of a jussive-causing condition is itself jussive. Its root ends in a weak letter, so the jussive is shown by dropping that letter and leaving the vowel before it. The verb is passive: ‘he will be requited with it’."],
    de: ["Das markierte Verb ist die Antwort auf die Bedingung. Wie lautet seine Form?", ["Jussiv Passiv, der schwache Endbuchstabe als Jussivzeichen weggefallen", "Nominativ mit gedachter Ḍamma auf dem letzten Alif", "Subjunktiv mit gedachter Fatḥa", "Auf Sukūn gebaut wie ein Perfekt"], "Die Antwort einer jussivbewirkenden Bedingung steht selbst im Jussiv. Ihre Wurzel endet auf einen schwachen Buchstaben, daher zeigt sich der Jussiv im Wegfall dieses Buchstabens und im Stehenlassen des Vokals davor. Das Verb ist passiv: ‚ihm wird damit vergolten‘."],
    ar: ["الفعل المظلل جواب الشرط. ما صورته؟", ["مضارع مبني للمجهول مجزوم وعلامة جزمه حذف حرف العلة", "مضارع مرفوع وعلامة رفعه ضمة مقدرة على الألف", "مضارع منصوب وعلامة نصبه فتحة مقدرة", "فعل مبني على السكون كالماضي"], "جواب الشرط الجازم مجزوم، ولما كان معتل الآخر فعلامة جزمه حذف حرف العلة مع بقاء الحركة قبله. والفعل مبني للمجهول."] },

  { id: "nhi-091", s: "nahw", g: 4, d: 5, t: ["qat-madh", "sibawayh"], src: "Sībawayh, al-Kitāb, chapter on what is put in the accusative for glorification and praise; al-Suyūṭī, al-Itqān, on difficult cases", v: "4:162", w: 15,
    en: ["This noun is accusative in the middle of a series of nominatives. Which explanation is attributed to Sībawayh?", ["Accusative of praise (madḥ) after an understood verb such as ‘I single out’, the series being cut off", "ʿAtf on the khabar of the series, with a normal accusative", "A ḥāl of the believers in the series", "A mafʿūl muṭlaq of the verb ‘they believe’"], "Sībawayh cites this verse as an example of qaṭʿ for praise: the speaker breaks the series by an accusative with an omitted verb, to stress the point. Other grammarians proposed coordination with an earlier word, but his explanation is the qaṭʿ one."],
    de: ["Dieses Nomen steht inmitten einer Reihe von Nominativen im Akkusativ. Welche Erklärung wird Sībawayh zugeschrieben?", ["Akkusativ des Lobes (madḥ) nach einem ergänzten Verb wie ‚ich hebe hervor‘, die Reihe wird unterbrochen", "ʿAṭf auf das Ḫabar der Reihe mit gewöhnlichem Akkusativ", "Ein Ḥāl der Gläubigen in der Reihe", "Ein Mafʿūl muṭlaq des Verbs ‚sie glauben‘"], "Sībawayh führt diesen Vers als Beispiel für Qaṭʿ zum Lob an: Der Sprecher unterbricht die Reihe durch einen Akkusativ mit ausgelassenem Verb, um den Punkt hervorzuheben. Andere Grammatiker erwogen eine Koordination mit einem früheren Wort, seine Erklärung ist aber die des Qaṭʿ."],
    ar: ["جاءت هذه الكلمة منصوبة وسط متتابعات مرفوعة. أي تفسير يُنسب إلى سيبويه؟", ["منصوبة على المدح بفعل محذوف تقديره أمدح أو أخص، مع قطع النعت", "معطوفة على خبر المتتابعات عطفًا عاديًّا", "حال من المؤمنين", "مفعول مطلق للفعل «يؤمنون»"], "ذكر سيبويه هذه الآية شاهدًا على القطع للمدح، فنُصبت المقيمين بفعل محذوف تنبيهًا على فضل الصلاة. وقال آخرون بالعطف على لفظ سابق، لكن المنسوب إليه هو القطع."] },

  { id: "nhi-092", s: "nahw", g: 4, d: 5, t: ["ishtighal", "shart"], src: "Sībawayh, al-Kitāb, chapter on the noun after in; Ibn Hishām, Mughnī al-Labīb, on the verb after the conditional particle", v: "9:6", w: 2,
    en: ["According to the Basran view, how is the nominative noun after the conditional ‘in’ analysed?", ["As the fāʿil of an omitted verb, explained by the verb that follows it", "As a mubtadaʾ whose khabar is the verb that follows", "As the ism of in, accusative", "As a ḥāl of the verb that follows"], "The Basrans (following Sībawayh) hold that the conditional particles ‘in’ and ‘idhā’ are followed by a verb, so a noun after them is a fāʿil of an omitted verb that the later verb interprets. Al-Akhfash and some others allowed a mubtadaʾ here."],
    de: ["Wie wird nach der Basrer Ansicht das Nomen im Nominativ nach dem konditionalen ‚in‘ analysiert?", ["Als Fāʿil eines ausgelassenen Verbs, das durch das folgende Verb erklärt wird", "Als Mubtadaʾ, dessen Ḫabar das folgende Verb ist", "Als Ism von in im Akkusativ", "Als Ḥāl des folgenden Verbs"], "Die Basrer (nach Sībawayh) vertreten, dass auf die Konditionalpartikeln ‚in‘ und ‚idhā‘ ein Verb folgt; ein Nomen danach ist daher Fāʿil eines ausgelassenen Verbs, das das spätere Verb auslegt. Al-Aḫfaš und einige andere erlaubten hier ein Mubtadaʾ."],
    ar: ["كيف يُعرب الاسم المرفوع بعد «إن» الشرطية على مذهب البصريين؟", ["فاعل لفعل محذوف يفسره الفعل المذكور بعده", "مبتدأ خبره الفعل بعده", "اسم «إن» منصوب", "حال للفعل بعده"], "يرى البصريون (تبعًا لسيبويه) أن أدوات الشرط «إن» و«إذا» لا يليها إلا فعل، فيكون الاسم بعدها فاعلًا لفعل محذوف يفسره الفعل المذكور، وأجاز الأخفش وبعضهم الابتداء."] },

  { id: "nhi-093", s: "nahw", g: 4, d: 5, t: ["kana-sisters", "dialects"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on mā, lā, lāta and in that work like laysa", v: "12:31", w: 27,
    en: ["The highlighted noun is accusative after the demonstrative. Which usage explains this?", ["The Ḥijāzī usage in which mā works like laysa: the demonstrative is its ism and this noun its khabar, accusative", "The Tamīmī usage in which mā does not work and the noun would be nominative", "A vocative", "A ḥāl of the demonstrative"], "In the dialect of the Ḥijāz, the negative mā works like laysa and puts the khabar in the accusative; the Banū Tamīm treat it as non-working and use the nominative. The verse shown follows the Ḥijāzī usage."],
    de: ["Das markierte Nomen steht nach dem Demonstrativum im Akkusativ. Welcher Sprachgebrauch erklärt das?", ["Der hidschasische Gebrauch, bei dem mā wie laysa wirkt: Das Demonstrativum ist sein Ism und dieses Nomen sein Ḫabar im Akkusativ", "Der tamimitische Gebrauch, bei dem mā nicht wirkt und das Nomen im Nominativ stünde", "Ein Vokativ", "Ein Ḥāl des Demonstrativums"], "Im Dialekt des Hidschaz wirkt das verneinende mā wie laysa und setzt das Ḫabar in den Akkusativ; die Banū Tamīm behandeln es als nicht wirkend und gebrauchen den Nominativ. Der gezeigte Vers folgt dem hidschasischen Gebrauch."],
    ar: ["الاسم المظلل منصوب بعد اسم الإشارة. أي لغة تفسّر ذلك؟", ["لغة الحجاز التي تُعمل «ما» عمل «ليس» فاسمها اسم الإشارة وخبرها هذه الكلمة المنصوبة", "لغة تميم التي تُهمل «ما» فيكون الاسم مرفوعًا", "منادى", "حال من اسم الإشارة"], "في لغة الحجاز تعمل «ما» النافية عمل «ليس» فتنصب الخبر، وبنو تميم يهملونها فيرفعون. والآية المعروضة على لغة الحجاز."] },

  { id: "nhi-094", s: "nahw", g: 4, d: 4, t: ["mafulat", "maful-mutlaq"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the absolute object (omitted verbs)", v: "17:1", w: 1,
    en: ["The verse opens with an accusative word. How is it analysed?", ["Mafʿūl muṭlaq of an obligatorily omitted verb (‘I declare … glorified’), annexed to the relative pronoun", "Mubtadaʾ, nominative", "Ḥāl of the speaker", "Khabar of an omitted mubtadaʾ"], "The word is a verbal noun that has taken the place of its verb; the verb is omitted by obligation (ḥadhf wājib), so the noun is accusative as mafʿūl muṭlaq and is annexed to ‘He who’."],
    de: ["Der Vers beginnt mit einem Akkusativwort. Wie wird es analysiert?", ["Mafʿūl muṭlaq eines zwingend ausgelassenen Verbs (‚ich preise … als erhaben‘), mit dem Relativpronomen verbunden", "Mubtadaʾ im Nominativ", "Ḥāl des Sprechers", "Ḫabar eines ausgelassenen Mubtadaʾ"], "Das Wort ist ein Verbalnomen, das an die Stelle seines Verbs getreten ist; das Verb ist zwingend ausgelassen (ḥaḏf wāǧib), daher steht das Nomen als Mafʿūl muṭlaq im Akkusativ und ist mit ‚der‘ verbunden."],
    ar: ["تبدأ الآية بكلمة منصوبة. كيف تُعرب؟", ["مفعول مطلق لفعل محذوف وجوبًا (أسبّح) وهو مضاف إلى الاسم الموصول", "مبتدأ مرفوع", "حال من المتكلم", "خبر لمبتدأ محذوف"], "الكلمة مصدر ناب عن فعله، وحذف فعله وجوبًا، فهي مفعول مطلق منصوب، وأُضيفت إلى الاسم الموصول."] },

  { id: "nhi-095", s: "nahw", g: 4, d: 4, t: ["ism-fil", "mabni-muarab"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the noun-verb (ismu al-fiʿl)", v: "17:23", w: 19,
    en: ["The highlighted word is an expression of disgust. What is its grammatical class?", ["An ism fiʿl muḍāriʿ (a noun standing for a verb meaning ‘I am annoyed’), built on kasra", "A muḍāf ilayhi in the genitive", "A mafʿūl muṭlaq in the accusative", "A mubtadaʾ in the nominative"], "Interjection-like words that stand for a verb are called asmāʾ al-afʿāl. This one stands for the present tense (‘I feel disgust’), is mabnī, and ends in kasra with tanwīn in this reading (tanwīn of indefiniteness)."],
    de: ["Das markierte Wort ist ein Ausdruck des Unmuts. Welcher grammatischen Klasse gehört es an?", ["Ein Ism fiʿl muḍāriʿ (ein Nomen anstelle eines Verbs mit der Bedeutung ‚ich bin verärgert‘), auf Kasra gebaut", "Ein Muḍāf ilayhi im Genitiv", "Ein Mafʿūl muṭlaq im Akkusativ", "Ein Mubtadaʾ im Nominativ"], "Interjektionsartige Wörter, die für ein Verb stehen, heißen Asmāʾ al-afʿāl. Dieses steht für die Gegenwart (‚ich empfinde Abscheu‘), ist mabnī und endet in dieser Lesart auf Kasra mit Tanwīn (Tanwīn der Unbestimmtheit)."],
    ar: ["الكلمة المظللة تعبّر عن التضجر. ما نوعها النحوي؟", ["اسم فعل مضارع بمعنى أتضجر مبني على الكسر", "مضاف إليه مجرور", "مفعول مطلق منصوب", "مبتدأ مرفوع"], "الألفاظ التي تنوب عن الأفعال تسمى أسماء الأفعال، وهذه بمعنى المضارع «أتضجّر»، وهي مبنية على الكسر، وتنوينها تنوين التنكير في هذه القراءة."] },

  { id: "nhi-096", s: "nahw", g: 4, d: 5, t: ["an-mudmara", "jazm-nasb"], src: "Ibn Hishām, Awḍaḥ al-Masālik, chapter on the subjunctive after lām al-taʿlīl", v: "17:1", w: 15,
    en: ["The highlighted verb begins with a lām. Which analysis is correct?", ["Lām al-taʿlīl; the verb is subjunctive by an understood an, with a visible fatḥa on the yāʾ", "Lām al-amr; the verb is jussive with the yāʾ dropped", "Lām al-ibtidāʾ; the verb is nominative with an implied ḍamma", "Lām al-jarr; the verb is a genitive noun"], "A lām followed by a verb to give a reason is lām al-taʿlīl, after which an is implied and puts the verb in the subjunctive; the yāʾ shows the fatḥa. Lām al-amr would give a jussive with the final yāʾ dropped, but the sense here is purpose, not command."],
    de: ["Das markierte Verb beginnt mit einem Lām. Welche Analyse trifft zu?", ["Lām al-taʿlīl; das Verb steht durch ein ergänztes an im Subjunktiv, mit sichtbarer Fatḥa auf dem Yāʾ", "Lām al-amr; das Verb steht im Jussiv, das Yāʾ fällt weg", "Lām al-ibtidāʾ; das Verb steht im Nominativ mit gedachter Ḍamma", "Lām al-ǧarr; das Verb ist ein Genitiv-Nomen"], "Ein Lām vor einem Verb, das einen Grund angibt, ist Lām al-taʿlīl, nach dem ein an ergänzt wird, das das Verb in den Subjunktiv setzt; das Yāʾ zeigt die Fatḥa. Lām al-amr würde den Jussiv mit Wegfall des Yāʾ ergeben, doch der Sinn ist hier ein Zweck, kein Befehl."],
    ar: ["الفعل المظلل يبدأ بلام. أي تحليل صحيح؟", ["لام التعليل والفعل منصوب بـ«أن» مضمرة وعلامة نصبه الفتحة الظاهرة على الياء", "لام الأمر والفعل مجزوم بحذف الياء", "لام الابتداء والفعل مرفوع بضمة مقدرة", "لام الجر والفعل اسم مجرور"], "اللام التي يليها فعل لبيان العلة هي لام التعليل، وبعدها «أن» مضمرة جوازًا تنصب الفعل، وتظهر الفتحة على الياء. أما لام الأمر فتجزم مع حذف الياء، وليس المعنى هنا معنى الأمر بل التعليل."] },

  { id: "nhi-097", s: "nahw", g: 4, d: 4, t: ["nun-tawkid", "mabni-muarab"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the nūn of emphasis", v: "7:23", w: 10,
    en: ["The highlighted verb answers a condition but is not jussive. Why?", ["Because it is built on fatḥa through direct contact with the heavy nūn of emphasis, and it answers an oath", "Because it is a perfect verb", "Because it is the khabar of kāna", "Because a nominative cannot follow in"], "A verb that directly meets the nūn of emphasis (nūn al-tawkīd) is mabnī on fatḥa and not declinable. The clause with lām is the answer of an implied oath, which takes the place of the answer of the condition."],
    de: ["Das markierte Verb beantwortet eine Bedingung, steht aber nicht im Jussiv. Warum?", ["Weil es durch unmittelbaren Kontakt mit dem schweren Nūn der Betonung auf Fatḥa gebaut ist und einen Schwur beantwortet", "Weil es ein Perfekt ist", "Weil es das Ḫabar von kāna ist", "Weil auf in kein Nominativ folgen kann"], "Ein Verb, das unmittelbar auf das Nūn der Betonung (Nūn al-tawkīd) trifft, ist auf Fatḥa gebaut und nicht deklinierbar. Der Satz mit Lām ist die Antwort auf einen ergänzten Schwur, der an die Stelle der Antwort der Bedingung tritt."],
    ar: ["الفعل المظلل جاء في جواب شرط ولم يُجزم. لماذا؟", ["لأنه مبني على الفتح لاتصاله مباشرة بنون التوكيد الثقيلة، وهو في جواب قسم", "لأنه فعل ماض", "لأنه خبر «كان»", "لأن «إن» لا يليها مرفوع"], "الفعل المضارع المتصل مباشرة بنون التوكيد مبني على الفتح، والجملة المقترنة باللام جواب لقسم مقدر يغني عن جواب الشرط."] },

  { id: "nhi-098", s: "nahw", g: 4, d: 4, t: ["hal-tamyiz", "tamyiz"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on the tamyīz (al-tamyīz al-muḥawwal ʿan al-mafʿūl)", v: "54:12", w: 3,
    en: ["The highlighted word is the specifier in ‘We made the earth burst forth …’. How is it classified?", ["Tamyīz converted from the object (‘We made the springs of the earth burst forth’)", "Tamyīz converted from the subject", "Ḥāl of the earth", "Mafʿūl muṭlaq"], "The original meaning is ‘We caused the springs of the earth to burst forth’: the object (springs) became a tamyīz and its muḍāf ilayhi (the earth) became the object. That is a tamyīz muḥawwal ʿan al-mafʿūl."],
    de: ["Das markierte Wort ist der Spezifizierer in ‚Wir ließen die Erde hervorbrechen …‘. Wie wird es eingeordnet?", ["Tamyīz, aus dem Objekt umgewandelt (‚Wir ließen die Quellen der Erde hervorbrechen‘)", "Tamyīz, aus dem Subjekt umgewandelt", "Ḥāl der Erde", "Mafʿūl muṭlaq"], "Die ursprüngliche Bedeutung ist ‚Wir ließen die Quellen der Erde hervorbrechen‘: Das Objekt (Quellen) wurde zum Tamyīz, und sein Muḍāf ilayhi (die Erde) wurde zum Objekt. Das ist ein Tamyīz muḥawwal ʿan al-mafʿūl."],
    ar: ["الكلمة المظللة تمييز في «وفجّرنا الأرض ...». كيف تُصنَّف؟", ["تمييز محوّل عن المفعول به (فجّرنا عيون الأرض)", "تمييز محوّل عن الفاعل", "حال من الأرض", "مفعول مطلق"], "الأصل «فجّرنا عيون الأرض»، فصار المفعول (عيونًا) تمييزًا وصار المضاف إليه (الأرض) مفعولًا به، وهذا هو التمييز المحوّل عن المفعول."] },

  { id: "nhi-099", s: "nahw", g: 4, d: 5, t: ["qiraat-nahw", "jazm-nasb"], src: "al-Zamakhsharī, al-Kashshāf, on 36:82; Ibn al-Jazarī, al-Nashr fī al-Qirāʾāt al-ʿAshr, on Yā Sīn", v: "36:82", w: 10,
    en: ["In the reading of Ḥafṣ this verb is nominative. How is the nominative explained?", ["The fāʾ is resumptive: it starts a new clause with an understood subject, ‘so it comes to be’", "The verb is the answer to an imperative, which requires the nominative", "The verb is jussive, written as nominative", "The verb is the khabar of an omitted inna"], "After a command, a verb with fāʾ can be accusative as a reply to the imperative, as some of the ten readers read it. Ḥafṣ reads it nominative: the clause is separate and means ‘and it then is’. The nominative presents the coming-to-be as a fresh statement."],
    de: ["In der Lesart von Ḥafṣ steht dieses Verb im Nominativ. Wie wird der Nominativ erklärt?", ["Das Fāʾ ist fortsetzend: Es beginnt einen neuen Satz mit einem ergänzten Subjekt, ‚so ist es‘", "Das Verb ist die Antwort auf einen Imperativ, die den Nominativ verlangt", "Das Verb ist ein Jussiv, als Nominativ geschrieben", "Das Verb ist das Ḫabar eines ausgelassenen inna"], "Nach einem Befehl kann ein Verb mit Fāʾ als Antwort auf den Imperativ im Akkusativ stehen, wie manche der zehn Leser es lesen. Ḥafṣ liest es im Nominativ: Der Satz ist eigenständig und bedeutet ‚und dann ist es‘. Der Nominativ stellt das Entstehen als neue Aussage dar."],
    ar: ["في رواية حفص رُفع هذا الفعل. كيف يُوجَّه الرفع؟", ["الفاء استئنافية والفعل خبر لمبتدأ محذوف تقديره «فهو يكون»", "الفعل جواب أمر ويلزم رفعه", "الفعل مجزوم كُتب مرفوعًا", "الفعل خبر لـ«إنّ» محذوفة"], "بعد الأمر يجوز نصب الفعل المقرون بالفاء جوابًا للأمر كما قرأ بعض القراء العشرة. أما حفص فرفع على الاستئناف، أي «فهو يكون»، فيكون الإيجاد إخبارًا مستأنفًا."] },

  { id: "nhi-100", s: "nahw", g: 4, d: 4, t: ["numbers", "mabni-muarab"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on compound numbers (al-ʿadad al-murakkab)", v: "2:60", w: 11,
    en: ["The highlighted word is the first part of the number twelve. How is the number ‘twelve’ treated?", ["The first part is declined like a dual (alif here, nominative), the second part is built on fatḥa", "Both parts are built on fatḥa", "Both parts are declined with their own endings", "The first part is built, the second declined"], "Compound numbers from 11 to 19 are built on fatḥa in both parts, with the exception of twelve: its first part (two) is declined like the dual and the second is built on fatḥa. Here it is the subject and takes the nominative alif."],
    de: ["Das markierte Wort ist der erste Teil der Zahl zwölf. Wie wird die Zahl ‚zwölf‘ behandelt?", ["Der erste Teil wird wie ein Dual dekliniert (hier Alif, Nominativ), der zweite ist auf Fatḥa gebaut", "Beide Teile sind auf Fatḥa gebaut", "Beide Teile werden mit eigenen Endungen dekliniert", "Der erste Teil ist gebaut, der zweite dekliniert"], "Die zusammengesetzten Zahlen 11 bis 19 sind in beiden Teilen auf Fatḥa gebaut, mit Ausnahme von zwölf: Ihr erster Teil (zwei) wird wie der Dual dekliniert, der zweite ist auf Fatḥa gebaut. Hier ist sie Subjekt und trägt das Nominativ-Alif."],
    ar: ["الكلمة المظللة الجزء الأول من العدد اثني عشر. كيف يُعامل هذا العدد؟", ["الجزء الأول يُعرب إعراب المثنى (بالألف رفعًا) والثاني مبني على الفتح", "الجزآن مبنيان على الفتح", "الجزآن معربان بعلاماتهما", "الأول مبني والثاني معرب"], "الأعداد المركبة من أحد عشر إلى تسعة عشر مبنية على فتح الجزأين إلا اثني عشر، فيعرب صدره إعراب المثنى ويُبنى عجزه على الفتح، وهنا فاعل مرفوع بالألف."] },

  { id: "nhi-101", s: "nahw", g: 4, d: 4, t: ["kana-sisters", "word-order"], src: "Ibn ʿAqīl, Sharḥ Alfiyya, chapter on kāna (the order of its ism and khabar)", v: "112:4", w: 5,
    en: ["The clause begins with a negated kāna, then a prepositional phrase and a noun with ‘equal’. What is the highlighted final word?", ["The ism of kāna, nominative, placed last", "The khabar of kāna, accusative", "A badal from the pronoun in the prepositional phrase", "A fāʿil of the prepositional phrase"], "The jussive kāna governs an ism and a khabar. The ism here is placed last because the khabar and the prepositional phrase come first (for emphasis on the negation of anything comparable). Hence the last word is nominative."],
    de: ["Der Satz beginnt mit einem verneinten kāna, dann folgen eine Präpositionalgruppe und ein Nomen mit der Bedeutung ‚gleich‘. Was ist das markierte letzte Wort?", ["Das Ism von kāna im Nominativ, an letzter Stelle", "Das Ḫabar von kāna im Akkusativ", "Ein Badal vom Pronomen in der Präpositionalgruppe", "Ein Fāʿil der Präpositionalgruppe"], "Das im Jussiv stehende kāna regiert ein Ism und ein Ḫabar. Das Ism steht hier an letzter Stelle, weil Ḫabar und Präpositionalgruppe vorangehen (zur Betonung der Verneinung von allem Vergleichbaren). Daher ist das letzte Wort im Nominativ."],
    ar: ["تبدأ الجملة بـ«كان» مجزومة منفية ثم شبه جملة وكلمة بمعنى «مكافئ». ما إعراب الكلمة الأخيرة المظللة؟", ["اسم «كان» مؤخّر مرفوع", "خبر «كان» منصوب", "بدل من الضمير في شبه الجملة", "فاعل لشبه الجملة"], "«كان» المجزومة ترفع الاسم وتنصب الخبر. والاسم هنا تأخر لأن الخبر وشبه الجملة تقدما لزيادة تأكيد نفي كل نظير، فالكلمة الأخيرة اسمها مرفوع."] },

  { id: "nhi-102", s: "nahw", g: 4, d: 4, t: ["pronouns", "mubtada-khabar"], src: "Ibn Hishām, Mughnī al-Labīb, on ḍamīr al-shaʾn", v: "112:1", w: 2,
    en: ["Which statement gives a recognised analysis of the highlighted pronoun?", ["Ḍamīr al-shaʾn (pronoun of the matter), a mubtadaʾ whose khabar is the entire clause after it", "A tawkīd of the imperative before it", "A mafʿūl bihi of the imperative, accusative", "A ḥāl, accusative"], "A third-person pronoun that comes at the head of a sentence without antecedent, and is explained by the sentence that follows, is ḍamīr al-shaʾn (or al-qiṣṣa). The pronoun is the mubtadaʾ, and the clause after it is its khabar. Other analyses take it as an ordinary mubtadaʾ with the divine name as khabar."],
    de: ["Welche Aussage gibt eine anerkannte Analyse des markierten Pronomens wieder?", ["Ḍamīr aš-šaʾn (Pronomen der Sache), ein Mubtadaʾ, dessen Ḫabar der ganze folgende Satz ist", "Ein Tawkīd des davorstehenden Imperativs", "Ein Mafʿūl bihi des Imperativs im Akkusativ", "Ein Ḥāl im Akkusativ"], "Ein Pronomen der dritten Person am Satzanfang ohne Bezugswort, das durch den folgenden Satz erklärt wird, ist Ḍamīr aš-šaʾn (oder al-qiṣṣa). Das Pronomen ist das Mubtadaʾ, der folgende Satz sein Ḫabar. Andere Analysen nehmen es als gewöhnliches Mubtadaʾ mit dem göttlichen Namen als Ḫabar."],
    ar: ["أي العبارات الآتية تذكر وجهًا معتمدًا في إعراب الضمير المظلل؟", ["ضمير الشأن مبتدأ وخبره الجملة بعده كلها", "توكيد لفعل الأمر قبله", "مفعول به لفعل الأمر منصوب", "حال منصوبة"], "الضمير الغائب في صدر الجملة بلا مرجع سابق يفسّره ما بعده يسمى ضمير الشأن (أو القصة)، وهو مبتدأ وخبره الجملة التالية. ومن النحاة من أعربه مبتدأ عاديًّا ولفظ الجلالة خبرًا."] },

  { id: "nhi-103", s: "nahw", g: 4, d: 4, t: ["hadhf", "mafulat"], src: "al-Zamakhsharī, al-Kashshāf, on 2:285; Ibn Hishām, Mughnī al-Labīb, on omitted verbs", v: "2:285", w: 24,
    en: ["The highlighted verbal noun is accusative, yet there is no verb governing it in the clause. How is it explained?", ["By an omitted verb such as ‘We ask for’, which the supplication implies", "By the verb ‘they said’ earlier in the clause, which takes it as a direct object", "By an omitted inna", "By annexation to the next word"], "Supplications often leave out the verb; a verbal noun such as ‘forgiveness’ is then accusative as a mafʿūl muṭlaq or object of an implied verb (we ask your forgiveness). The next word ‘our Lord’ is a separate vocative."],
    de: ["Das markierte Verbalnomen steht im Akkusativ, doch im Satz regiert es kein Verb. Wie wird das erklärt?", ["Durch ein ausgelassenes Verb wie ‚wir erbitten‘, das das Bittgebet mitdenkt", "Durch das frühere Verb ‚sie sagten‘, das es als direktes Objekt nimmt", "Durch ein ausgelassenes inna", "Durch Verbindung mit dem nächsten Wort"], "In Bittgebeten wird das Verb oft ausgelassen; ein Verbalnomen wie ‚Vergebung‘ steht dann im Akkusativ als Mafʿūl muṭlaq oder Objekt eines ergänzten Verbs (wir erbitten Vergebung). Das nächste Wort ‚unser Herr‘ ist ein eigener Vokativ."],
    ar: ["المصدر المظلل منصوب ولا فعل يعمل فيه في الجملة. كيف يُفسَّر النصب؟", ["بفعل محذوف تقديره نسأل أو نطلب، يقتضيه سياق الدعاء", "بالفعل «قالوا» السابق الذي ينصبه مفعولًا به", "بـ«إنّ» محذوفة", "بالإضافة إلى الكلمة بعده"], "كثيرًا ما يُحذف الفعل في الدعاء، فيُنصب المصدر (غفرانك) على المفعولية المطلقة أو المفعول به لفعل مقدر أي نسألك غفرانك. و«ربنا» بعده منادى مستقل."] },
];
